@import url('https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&display=swap');

:root {
  font-family: 'Manrope', sans-serif;
  color: #f6f9fc;
  background: #06111f;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background:
    radial-gradient(
      circle at 80% 0%,
      rgba(36, 105, 179, 0.28),
      transparent 35%
    ),
    #06111f;
}

button,
input {
  font: inherit;
}

button {
  -webkit-tap-highlight-color: transparent;
}

.login-page,
.dashboard-page {
  min-height: 100vh;
  padding: 24px 18px;
}

.login-container {
  width: 100%;
  max-width: 470px;
  margin: 0 auto;
}

.brand,
.brand-small {
  display: flex;
  align-items: center;
  gap: 12px;
}

.logo,
.logo-small {
  display: grid;
  place-items: center;
  background: linear-gradient(
    135deg,
    #1bd7ff,
    #377cff
  );
  color: #04111c;
  font-weight: 800;
  box-shadow: 0 12px 32px rgba(27, 215, 255, 0.25);
}

.logo {
  width: 52px;
  height: 52px;
  border-radius: 17px;
  font-size: 20px;
}

.logo-small {
  width: 42px;
  height: 42px;
  border-radius: 13px;
}

.brand h1 {
  margin: 0;
  font-size: 19px;
}

.brand p {
  margin: 2px 0 0;
  color: #8498ad;
  font-size: 13px;
}

.welcome {
  margin: 48px 0 27px;
}

.eyebrow {
  color: #21d2fb;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
}

.welcome h2 {
  margin: 10px 0;
  font-size: clamp(32px, 9vw, 46px);
  line-height: 1.1;
}

.welcome h2 span {
  display: block;
  color: #23cefa;
}

.welcome p {
  color: #91a3b6;
  line-height: 1.7;
}

.role-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-bottom: 25px;
}

.role-card {
  min-height: 78px;
  padding: 12px;
  display: flex;
  align-items: center;
  gap: 10px;
  text-align: left;
  color: #a8b8c8;
  background: #0c1928;
  border: 1px solid #1e3448;
  border-radius: 15px;
  cursor: pointer;
}

.role-card.active {
  color: #ffffff;
  background: #0b2a3a;
  border-color: #1bd7ff;
  box-shadow: 0 0 25px rgba(27, 215, 255, 0.1);
}

.role-icon {
  font-size: 25px;
}

.role-text strong,
.role-text small {
  display: block;
}

.role-text small {
  margin-top: 3px;
  color: #71879c;
  font-size: 10px;
  line-height: 1.3;
}

.form-field {
  display: block;
  margin-top: 17px;
}

.form-field > span {
  display: block;
  margin-bottom: 8px;
  color: #a6b5c4;
  font-size: 13px;
}

.form-field input {
  width: 100%;
  min-height: 52px;
  padding: 13px 14px;
  color: #ffffff;
  background: #081422;
  border: 1px solid #20364a;
  border-radius: 13px;
  outline: none;
  font-size: 16px;
}

.form-field input:focus {
  border-color: #1bd7ff;
}

.password-field {
  position: relative;
}

.password-field input {
  padding-right: 105px;
}

.show-password {
  position: absolute;
  top: 6px;
  right: 7px;
  min-height: 40px;
  padding: 0 10px;
  color: #2ed7ff;
  background: transparent;
  border: 0;
  cursor: pointer;
  font-size: 12px;
}

.login-button {
  width: 100%;
  min-height: 54px;
  margin-top: 22px;
  color: #03111c;
  background: linear-gradient(
    90deg,
    #1bd7ff,
    #367dff
  );
  border: 0;
  border-radius: 14px;
  font-weight: 800;
  cursor: pointer;
}

.login-button:disabled {
  cursor: wait;
  opacity: 0.7;
}

.error-message {
  margin-top: 16px;
  padding: 12px 14px;
  color: #ffbbc4;
  background: rgba(130, 25, 44, 0.3);
  border: 1px solid #793140;
  border-radius: 12px;
  font-size: 13px;
}

.security-note {
  margin: 21px 0 0;
  color: #63788e;
  text-align: center;
  font-size: 11px;
}

.dashboard-page {
  max-width: 700px;
  margin: auto;
}

.dashboard-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.brand-small strong,
.brand-small span {
  display: block;
}

.brand-small span {
  color: #8195aa;
  font-size: 12px;
}

.logout-button {
  min-height: 44px;
  padding: 0 16px;
  color: #aebdcc;
  background: #0c1928;
  border: 1px solid #21384c;
  border-radius: 12px;
  cursor: pointer;
}

.welcome-card {
  margin-top: 28px;
  padding: 25px;
  background: linear-gradient(
    145deg,
    #0d1d2e,
    #091523
  );
  border: 1px solid #1c354a;
  border-radius: 22px;
}

.status-badge {
  color: #43dfa4;
  font-size: 11px;
  font-weight: 700;
}

.welcome-card p {
  margin: 35px 0 5px;
  color: #8da0b4;
}

.welcome-card h1 {
  margin: 0 0 30px;
  color: #25d0fb;
  font-size: 34px;
}

.role-information {
  display: flex;
  justify-content: space-between;
  padding: 15px;
  background: #07121f;
  border-radius: 13px;
}

.role-information span {
  color: #8498ac;
}

.dashboard-note {
  margin-top: 25px !important;
  line-height: 1.7;
}

@media (min-width: 768px) {
  .login-page {
    display: grid;
    place-items: center;
    padding: 45px;
  }

  .login-container {
    padding: 36px;
    background: rgba(7, 18, 31, 0.72);
    border: 1px solid #1b3348;
    border-radius: 27px;
  }

  .welcome {
    margin-top: 36px;
  }
}

.app-dashboard {
  width: 100%;
  max-width: 1100px;
  min-height: 100vh;
  margin: 0 auto;
  padding: 20px 18px 95px;
}

.app-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.dashboard-welcome {
  margin: 28px 0 20px;
  padding: 22px;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 18px;
  background: linear-gradient(145deg, #0d2134, #0a1725);
  border: 1px solid #1d3c55;
  border-radius: 21px;
}

.system-connected {
  color: #39e2a0;
  font-size: 11px;
  font-weight: 700;
}

.dashboard-welcome h1 {
  margin: 20px 0 8px;
  font-size: clamp(26px, 7vw, 39px);
}

.dashboard-welcome h1 span {
  display: block;
  color: #22cff8;
}

.dashboard-welcome p {
  margin: 0;
  color: #8da1b5;
}

.refresh-button {
  min-height: 44px;
  padding: 0 14px;
  color: #22cff8;
  background: #081522;
  border: 1px solid #21425a;
  border-radius: 12px;
  cursor: pointer;
  white-space: nowrap;
}

.dashboard-loading,
.empty-state {
  padding: 35px 20px;
  color: #8da1b5;
  text-align: center;
  background: #0b1827;
  border-radius: 17px;
}

.metric-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 11px;
}

.metric-card {
  min-width: 0;
  padding: 17px;
  background: linear-gradient(145deg, #0d1c2c, #091522);
  border: 1px solid #1c3449;
  border-radius: 17px;
}

.metric-icon {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  margin-bottom: 16px;
  background: #0b2b3a;
  border-radius: 11px;
}

.metric-card small {
  display: block;
  color: #8297ab;
  font-size: 11px;
}

.metric-card strong {
  display: block;
  margin-top: 6px;
  overflow-wrap: anywhere;
  font-size: clamp(19px, 5vw, 29px);
}

.dashboard-section {
  margin-top: 16px;
  padding: 19px;
  background: #0b1827;
  border: 1px solid #1b3348;
  border-radius: 19px;
}

.section-heading {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 12px;
  margin-bottom: 17px;
}

.section-heading h2 {
  margin: 5px 0 0;
  font-size: 19px;
}

.data-count {
  color: #8095a9;
  font-size: 11px;
  white-space: nowrap;
}

.payment-item {
  display: grid;
  grid-template-columns: 42px 1fr auto;
  gap: 11px;
  align-items: center;
  padding: 14px 0;
  border-bottom: 1px solid #1a2e41;
}

.payment-item:last-child {
  border-bottom: 0;
}

.payment-avatar {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  color: #22cff8;
  background: #0c2c3d;
  border-radius: 13px;
  font-weight: 700;
}

.payment-information {
  min-width: 0;
}

.payment-information strong,
.payment-information span,
.payment-information small {
  display: block;
}

.payment-information strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.payment-information span,
.payment-information small {
  margin-top: 3px;
  color: #7f94a8;
  font-size: 10px;
}

.payment-amount {
  text-align: right;
}

.payment-amount strong,
.payment-amount span {
  display: block;
}

.payment-amount strong {
  color: #39e2a0;
  font-size: 13px;
}

.payment-amount span {
  margin-top: 4px;
  color: #8297ab;
  font-size: 9px;
}

.mobile-navigation {
  position: fixed;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 10;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  padding: 7px 8px 10px;
  background: rgba(7, 18, 31, 0.97);
  border-top: 1px solid #1c3449;
  backdrop-filter: blur(15px);
}

.mobile-navigation button {
  min-height: 55px;
  color: #71869b;
  background: transparent;
  border: 0;
  font-size: 10px;
}

.mobile-navigation button span {
  display: block;
  margin-bottom: 3px;
  font-size: 19px;
}

.mobile-navigation button.active {
  color: #23cff8;
}

@media (max-width: 520px) {
  .dashboard-welcome {
    align-items: flex-start;
    flex-direction: column;
  }

  .refresh-button {
    width: 100%;
  }

  .payment-item {
    grid-template-columns: 38px 1fr;
  }

  .payment-amount {
    grid-column: 2;
    text-align: left;
  }
}

@media (min-width: 768px) {
  .metric-grid {
    grid-template-columns: repeat(4, 1fr);
  }

  .mobile-navigation {
    left: 50%;
    width: 700px;
    transform: translateX(-50%);
  }
}

.students-page {
  margin-top: 28px;
}

.page-heading h1 {
  margin: 8px 0 4px;
  font-size: clamp(28px, 7vw, 38px);
}

.page-heading p {
  margin: 0;
  color: #8297ab;
  font-size: 12px;
}

.student-search {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 9px;
  margin: 20px 0 16px;
}

.student-search input {
  width: 100%;
  min-width: 0;
  padding: 13px 14px;
  color: #ffffff;
  background: #081522;
  border: 1px solid #20394e;
  border-radius: 13px;
  outline: none;
}

.student-search input:focus {
  border-color: #23cff8;
}

.student-search button,
.pagination button {
  padding: 0 17px;
  color: #04111c;
  background: #23cff8;
  border: 0;
  border-radius: 12px;
  font-weight: 800;
  cursor: pointer;
}

.student-list {
  display: grid;
  gap: 10px;
}

.student-card {
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr);
  gap: 13px;
  padding: 16px;
  background: linear-gradient(145deg, #0d1c2c, #091522);
  border: 1px solid #1c3449;
  border-radius: 17px;
}

.student-avatar {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  color: #23cff8;
  background: #0b2b3a;
  border-radius: 14px;
  font-size: 18px;
  font-weight: 800;
}

.student-info {
  min-width: 0;
}

.student-name-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 10px;
}

.student-name-row strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.student-status {
  flex-shrink: 0;
  padding: 4px 8px;
  color: #ffc16b;
  background: rgba(255, 173, 51, 0.12);
  border-radius: 99px;
  font-size: 9px;
  font-weight: 700;
}

.student-status.active {
  color: #43dfa4;
  background: rgba(67, 223, 164, 0.12);
}

.student-info > span,
.student-info small {
  display: block;
  margin-top: 4px;
  color: #748a9f;
  font-size: 10px;
}

.student-info p {
  margin: 8px 0 0;
  color: #b4c2cf;
  font-size: 12px;
}

.pagination {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  margin-top: 18px;
}

.pagination button {
  min-height: 40px;
  font-size: 11px;
}

.pagination button:disabled {
  cursor: not-allowed;
  opacity: 0.35;
}

.pagination span {
  color: #8297ab;
  text-align: center;
  font-size: 10px;
}

.coming-soon {
  margin-top: 28px;
  padding: 30px 20px;
  text-align: center;
  background: #0b1827;
  border: 1px solid #1b3348;
  border-radius: 19px;
}

.coming-soon h2 {
  margin: 10px 0;
}

.coming-soon p {
  color: #8297ab;
}

@media (max-width: 420px) {
  .student-search {
    grid-template-columns: 1fr;
  }

  .student-search button {
    min-height: 45px;
  }

  .pagination {
    flex-wrap: wrap;
  }
}

/* Tampilan login baru — tempelkan paling bawah di src/index.css */
.reference-login-page {
  min-height: 100vh;
  padding: 30px 18px 44px;
}

.reference-login-container {
  position: relative;
  width: 100%;
  max-width: 610px;
  margin: 0 auto;
  padding: 0;
  background: transparent;
  border: 0;
}

.language-switch {
  position: absolute;
  top: 0;
  right: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  padding: 5px;
  background: #0c1928;
  border: 1px solid #23394d;
  border-radius: 14px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
}

.language-switch button {
  min-width: 48px;
  min-height: 40px;
  color: #667b90;
  background: transparent;
  border: 0;
  border-radius: 10px;
  cursor: pointer;
  font-weight: 800;
}

.language-switch button.active {
  color: #03111c;
  background: #22cff8;
  box-shadow: 0 0 18px rgba(34, 207, 248, 0.28);
}

.login-brand {
  padding-top: 62px;
  text-align: center;
}

.login-brand-mark {
  display: grid;
  place-items: center;
  width: 78px;
  height: 78px;
  margin: 0 auto 22px;
  color: #03111c;
  background: linear-gradient(145deg, #25dcff, #287cff);
  border-radius: 23px 8px 23px 8px;
  box-shadow: 0 0 35px rgba(35, 207, 248, 0.25);
  font-size: 25px;
  font-weight: 800;
  transform: rotate(-6deg);
}

.login-brand-mark::first-line {
  transform: rotate(6deg);
}

.login-brand h1 {
  margin: 0;
  color: #ffffff;
  font-size: clamp(27px, 7vw, 39px);
}

.login-brand p {
  margin: 10px 0 0;
  color: #23cff8;
  font-size: 14px;
  font-weight: 800;
  letter-spacing: 0.18em;
}

.login-card {
  margin-top: 48px;
  padding: clamp(25px, 7vw, 48px);
  background: linear-gradient(145deg, #101e2a, #0b1825);
  border: 1px solid #263949;
  border-radius: 28px;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.24);
}

.login-card-heading h2 {
  margin: 0;
  color: #ffffff;
  font-size: clamp(29px, 7vw, 42px);
  line-height: 1.15;
}

.login-card-heading p {
  margin: 12px 0 30px;
  color: #8c9bad;
  line-height: 1.6;
}

.login-card .form-field {
  margin-top: 21px;
}

.login-card .form-field > span {
  margin-bottom: 10px;
  color: #aab6c2;
  font-weight: 700;
}

.login-card .form-field input {
  min-height: 62px;
  padding: 16px 18px;
  background: #08111d;
  border-color: #344253;
  border-radius: 16px;
}

.login-card .password-field input {
  padding-right: 105px;
}

.login-card .show-password {
  top: 11px;
  right: 10px;
}

.login-options {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 15px;
  margin-top: 22px;
}

.remember-option {
  display: flex;
  align-items: center;
  gap: 9px;
  color: #a5b2bf;
  font-size: 13px;
  cursor: pointer;
}

.remember-option input {
  width: 18px;
  height: 18px;
  accent-color: #22cff8;
}

.forgot-password {
  padding: 5px 0;
  color: #23cff8;
  background: transparent;
  border: 0;
  cursor: pointer;
  font-size: 13px;
  font-weight: 800;
}

.login-card .login-button {
  min-height: 62px;
  margin-top: 27px;
  border-radius: 16px;
  font-size: 17px;
}

.login-card .security-note {
  margin-top: 23px;
  line-height: 1.5;
}

@media (max-width: 440px) {
  .reference-login-page {
    padding: 21px 14px 30px;
  }

  .language-switch button {
    min-width: 40px;
    min-height: 36px;
  }

  .login-brand {
    padding-top: 70px;
  }

  .login-card {
    margin-top: 36px;
    border-radius: 23px;
  }

  .login-options {
    align-items: flex-start;
    flex-direction: column;
  }
}

/* Ukuran logo pesawat pada halaman login */
.login-logo-frame {
  width: 80px !important;
  height: 80px !important;
  margin: 0 auto !important;
  padding: 10px !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

.login-brand-logo {
  width: 60px !important;
  height: 60px !important;
  object-fit: contain !important;
  filter: brightness(0) saturate(100%)
    invert(69%) sepia(76%) saturate(624%)
    hue-rotate(135deg) brightness(89%) contrast(90%);
}

.login-brand-name {
  margin: 10px 0 2px;
  color: #ffffff;
  font-size: 23px;
  font-weight: 800;
  line-height: 1.2;
  text-align: center;
}

.login-brand > p {
  margin: 4px 0 0;
  color: #25c5d4;
  font-size: 23px;
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: 0.04em;
  text-align: center;
  text-transform: uppercase;
}

/* Paksa ukuran logo di dalam dashboard */
.dashboard-logo-frame {
  display: grid !important;
  place-items: center !important;
  flex: 0 0 52px !important;
  width: 52px !important;
  height: 52px !important;
  min-width: 52px !important;
  max-width: 52px !important;
  padding: 8px !important;
  overflow: hidden !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

.dashboard-brand-logo,
.dashboard-logo-frame img {
  display: block !important;
  width: 36px !important;
  height: 36px !important;
  min-width: 36px !important;
  max-width: 36px !important;
  object-fit: contain !important;
  filter: brightness(0) saturate(100%)
    invert(69%) sepia(76%) saturate(624%)
    hue-rotate(135deg) brightness(89%) contrast(90%);
}

/* STUDENT MAIN MENU — tempel paling bawah src/index.css */
.student-main-menu {
  width: 100%;
  max-width: 760px;
  min-height: 100vh;
  margin: 0 auto;
  padding: 0 18px 32px;
  color: #f7fafc;
  background: #07111f;
}

.student-menu-header {
  position: sticky;
  top: 0;
  z-index: 20;
  display: grid;
  grid-template-columns: 44px 1fr auto 44px;
  gap: 10px;
  align-items: center;
  min-height: 82px;
  background: rgba(7, 17, 31, 0.96);
  border-bottom: 1px solid #1b3041;
  backdrop-filter: blur(14px);
}

.student-menu-header > strong {
  color: #25c5d4;
  font-size: clamp(17px, 5vw, 24px);
  letter-spacing: 0.04em;
}

.student-menu-button,
.student-refresh {
  width: 44px;
  height: 44px;
  padding: 0;
  color: #25c5d4;
  background: transparent;
  border: 0;
  cursor: pointer;
  font-size: 31px;
}

