.academic-overview { margin-top: 26px; }
.academic-heading { display:flex; justify-content:space-between; align-items:end; gap:14px; margin-bottom:16px; }
.academic-heading span { color:#25c5d4; font-size:11px; font-weight:800; letter-spacing:.08em; }
.academic-heading h2 { margin:5px 0 0; font-size:clamp(23px,6vw,32px); }
.academic-heading > button { width:42px; height:42px; color:#25c5d4; background:#0c1928; border:1px solid #1c3c4b; border-radius:13px; font-size:24px; cursor:pointer; }
.next-class-card { width:100%; padding:22px; color:#fff; text-align:left; background:linear-gradient(135deg,rgba(16,156,175,.22),#0b1927); border:1px solid rgba(37,197,212,.48); border-radius:22px; cursor:pointer; }
.next-class-card span,.next-class-card strong,.next-class-card small { display:block; }
.next-class-card span { color:#25c5d4; font-size:11px; font-weight:800; letter-spacing:.1em; }
.next-class-card strong { margin-top:10px; font-size:24px; }
.next-class-card p { margin:7px 0; color:#bdc9d3; }
.next-class-card small { color:#8497a7; }
.academic-card-grid { display:grid; grid-template-columns:repeat(2,1fr); gap:11px; margin-top:12px; }
.academic-card-grid button { min-width:0; min-height:142px; padding:18px; color:#fff; text-align:left; background:#0c1928; border:1px solid #1c3448; border-radius:19px; cursor:pointer; }
.academic-card-grid span,.academic-card-grid strong,.academic-card-grid small { display:block; }
.academic-card-grid span { color:#7f94a6; font-size:10px; font-weight:800; letter-spacing:.07em; }
.academic-card-grid strong { margin:15px 0 7px; color:#25c5d4; font-size:clamp(23px,6vw,32px); }
.academic-card-grid .program-name { font-size:20px; }
.academic-card-grid small { color:#8294a4; line-height:1.45; }
.paid { color:#39e2a0 !important; }
.unpaid { color:#f6c344 !important; }
.full-report-button { width:100%; min-height:52px; margin-top:13px; color:#07111f; background:linear-gradient(90deg,#25c5d4,#f6c344); border:0; border-radius:15px; font-weight:800; cursor:pointer; }
.student-detail-page { width:100%; max-width:760px; min-height:100vh; margin:0 auto; padding:18px 18px 50px; color:#f7fafc; background:#07111f; }
.student-detail-page > header { display:flex; gap:14px; align-items:center; min-height:65px; border-bottom:1px solid #1b3041; }
.student-detail-page > header button { width:42px; height:42px; color:#25c5d4; background:#0c1928; border:1px solid #1c3448; border-radius:13px; font-size:23px; cursor:pointer; }
.student-detail-page > header h1 { margin:0; font-size:21px; }
.detail-panel { margin-top:22px; padding:22px; background:#0c1928; border:1px solid #1c3448; border-radius:22px; }
.detail-panel h2 { margin:7px 0 16px; color:#f7fafc; }
.detail-panel > p { color:#8fa1b1; }
.detail-label { color:#25c5d4; font-size:10px; font-weight:800; letter-spacing:.1em; }
.detail-row { display:flex; justify-content:space-between; gap:18px; align-items:center; padding:14px 0; border-bottom:1px solid #1a2e40; }
.detail-row:last-of-type { border-bottom:0; }
.detail-row span { color:#8fa1b1; }
.detail-row strong { text-align:right; }
.detail-action { display:block; margin-top:17px; padding:14px; color:#07111f; text-align:center; text-decoration:none; background:#25c5d4; border-radius:13px; font-weight:800; }
.attendance-breakdown { display:grid; grid-template-columns:repeat(4,1fr); gap:8px; margin:18px 0; }
