.attendance-breakdown strong { margin-top:7px; font-size:20px; }
.student-logout-detail { width:100%; min-height:48px; margin-top:22px; color:#ff9ba4; background:rgba(154,35,52,.18); border:1px solid #713040; border-radius:13px; cursor:pointer; }
.empty-feature { padding:45px 22px; text-align:center; }
