.student-main-menu {
  width: 100%;
  max-width: 760px;
  min-height: 100vh;
  margin: 0 auto;
  padding: 0 18px 32px;
  color: #f7fafc;
  background: #07111f;
}

.student-menu-header {
  position: sticky;
  top: 0;
  z-index: 40;
  display: grid;
  grid-template-columns: 44px 1fr auto 44px;
  gap: 10px;
  align-items: center;
  min-height: 82px;
  background: rgba(7, 17, 31, 0.96);
  border-bottom: 1px solid #1b3041;
  backdrop-filter: blur(14px);
}

.student-menu-header > strong {
  color: #25c5d4;
  font-size: clamp(17px, 5vw, 24px);
  letter-spacing: 0.04em;
}

.student-main-menu-link {
  padding: 0;
  color: #25c5d4;
  text-align: left;
  background: transparent;
  border: 0;
  cursor: pointer;
  font-size: clamp(17px, 5vw, 24px);
  font-weight: 800;
  letter-spacing: .04em;
}

.student-menu-button,
.student-refresh {
  width: 44px;
  height: 44px;
  padding: 0;
  color: #25c5d4;
  background: transparent;
  border: 0;
  cursor: pointer;
  font-size: 31px;
}

.student-refresh {
  font-size: 34px;
}

.cloud-status {
  padding: 10px 14px;
  color: #39e2a0;
  border: 1px solid rgba(57, 226, 160, 0.45);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
}

.student-drawer {
  position: fixed;
  top: 76px;
  left: max(18px, calc(50% - 362px));
  z-index: 50;
  display: grid;
  width: min(270px, calc(100vw - 36px));
  padding: 12px;
  background: #0c1928;
  border: 1px solid #1d3c4c;
  border-radius: 16px;
  box-shadow: 0 22px 55px rgba(0, 0, 0, 0.45);
  max-height: calc(100vh - 100px);
  overflow-y: auto;
}

.student-drawer-backdrop {
  position: fixed;
  inset: 0;
  z-index: 25;
  padding: 0;
  background: rgba(2, 8, 15, .58);
  border: 0;
  cursor: default;
}

.student-drawer button {
  min-height: 50px;
  padding: 13px 14px;
  color: #dce7ef;
  text-align: left;
  background: transparent;
  border: 0;
  border-bottom: 1px solid #1a2d3d;
  cursor: pointer;
}

.student-drawer button:last-child {
  border-bottom: 0;
}

.student-drawer .student-logout {
  color: #ff8f99;
}

.student-hero-card {
  margin-top: 28px;
  padding: clamp(24px, 6vw, 42px);
  background: linear-gradient(145deg, #0c1b29, #0a1724);
  border: 1px solid rgba(37, 197, 212, 0.48);
  border-radius: 32px;
  box-shadow: inset 0 0 30px rgba(37, 197, 212, 0.03);
}

.student-sun-icon {
