}

.weather-main {
  display: grid;
  grid-template-columns: 74px 1fr auto;
  gap: 18px;
  align-items: center;
  padding-bottom: 23px;
  border-bottom: 1px solid #263544;
}

.weather-icon {
  display: grid;
  place-items: center;
  width: 74px;
  height: 74px;
  background: #121d2d;
  border-radius: 21px;
