html[data-theme='dark'] .report-comments blockquote,
html[data-theme='dark'] .report-table-scroll,
html[data-theme='dark'] .report-empty { background:#0b1420; border-color:#2a3a48; }
html[data-theme='dark'] .report-attendance-card > p,
html[data-theme='dark'] .report-grade-card > div { background:#151f2b; }
html[data-theme='dark'] .report-attendance-card > p b,
html[data-theme='dark'] .report-comments blockquote,
html[data-theme='dark'] .report-table-scroll td { color:#dbe5ec; }
