.weather-main {
  display: grid;
  grid-template-columns: 74px 1fr auto;
  gap: 18px;
  align-items: center;
  padding-bottom: 23px;
  border-bottom: 1px solid #263544;
}

.weather-icon {
  display: grid;
  place-items: center;
  width: 74px;
  height: 74px;
  background: #121d2d;
  border-radius: 21px;
  font-size: 39px;
}

.weather-main strong,
.weather-main span {
  display: block;
}

.weather-main strong {
  font-size: clamp(32px, 8vw, 48px);
}

.weather-main div > span {
  margin-top: 4px;
  color: #25c5d4;
  font-weight: 800;
  text-transform: uppercase;
}

.weather-main p {
  margin: 0;
  color: #a4b1bd;
  font-weight: 700;
}

.weather-details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-top: 20px;
}

.weather-details div {
  min-width: 0;
  padding: 15px 8px;
  text-align: center;
  background: #111927;
  border: 1px solid #253343;
  border-radius: 17px;
}

.weather-details span,
.weather-details strong {
  display: block;
}

.weather-details span {
  color: #778797;
  font-size: 10px;
  font-weight: 800;
}

.weather-details strong {
  margin-top: 10px;
  font-size: clamp(13px, 3.8vw, 18px);
}

.weather-unavailable {
  padding: 30px 15px;
  color: #8fa0af;
  text-align: center;
}

.student-system-status {
  display: flex;
  gap: 17px;
  align-items: center;
  margin-top: 25px;
  padding: 22px;
  background: rgba(28, 134, 109, 0.2);
  border: 1px solid rgba(57, 226, 160, 0.37);
  border-radius: 22px;
}

.student-system-status > span {
  display: grid;
  place-items: center;
  width: 59px;
  height: 59px;
  color: #39e2a0;
  background: rgba(57, 226, 160, 0.13);
  border-radius: 17px;
  font-size: 29px;
}

.student-system-status small,
.student-system-status strong {
  display: block;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.student-system-status small {
  color: #99a8b4;
}

.student-system-status strong {
  margin-top: 4px;
  color: #39e2a0;
  font-size: 20px;
}

.student-quick-menu {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  margin-top: 17px;
}

.student-quick-menu button {
  min-height: 82px;
  padding: 10px 6px;
  color: #9dabb8;
  background: #0c1928;
  border: 1px solid #1c3448;
  border-radius: 17px;
  cursor: pointer;
  font-size: 11px;
}

.student-quick-menu button span {
  display: block;
  margin-bottom: 7px;
  color: #25c5d4;
  font-size: 24px;
}

@media (max-width: 560px) {
  .student-menu-header {
    grid-template-columns: 38px 1fr 38px;
  }

  .cloud-status {
    display: none;
  }

  .student-menu-button,
  .student-refresh {
    width: 38px;
  }

  .weather-main {
    grid-template-columns: 62px 1fr;
  }

  .weather-icon {
    width: 62px;
    height: 62px;
  }

  .weather-main p {
    grid-column: 2;
    margin-top: -12px;
  }

  .student-quick-menu {
    grid-template-columns: repeat(2, 1fr);
  }
}

