.quest-progress-row > strong { color:#39e2a0; font-size:12px; }
@media (max-width:480px) {
  .exp-meta { align-items:flex-start; flex-direction:column; }
  .exp-meta span { text-align:left; }
  .quest-item { grid-template-columns:46px minmax(0,1fr); padding:15px; }
  .quest-icon { width:46px; height:46px; }
