/* Tutor monthly student report */
.tutor-report-launch { display:grid; grid-template-columns:48px minmax(0,1fr) auto; gap:13px; align-items:center; width:100%; margin-top:22px; padding:15px; color:#eef5f8; text-align:left; background:linear-gradient(135deg,rgba(47,124,246,.14),rgba(37,197,212,.08)); border:1px solid rgba(65,151,255,.35); border-radius:17px; cursor:pointer; }
.tutor-report-launch > span { display:grid; place-items:center; width:46px; height:46px; color:#fff; background:#2679e8; border-radius:13px; font-size:21px; }
.tutor-report-launch strong,.tutor-report-launch small { display:block; }
.tutor-report-launch small { margin-top:4px; color:#91a7b7; font-size:12px; }
.tutor-report-launch > b { color:#59a2ff; }
.tutor-report-page { margin-top:22px; }
.tutor-report-toolbar { display:flex; gap:12px; align-items:end; margin-bottom:14px; padding:14px; color:#eef5f8; background:#0c1826; border:1px solid #294152; border-radius:16px; }
.tutor-report-toolbar > button { min-height:42px; padding:0 14px; color:#25c5d4; background:#091522; border:1px solid #285065; border-radius:10px; cursor:pointer; font-weight:800; }
.tutor-report-toolbar label { display:grid; gap:5px; margin-left:auto; }
.tutor-report-toolbar label span { color:#91a7b7; font-size:11px; font-weight:800; }
.tutor-report-toolbar input { min-height:42px; padding:0 11px; color:#eef5f8; background:#081521; border:1px solid #2b4253; border-radius:10px; }
.tutor-report-toolbar .print-report-button { color:#06111f; background:#25c5d4; border-color:#25c5d4; }
.tutor-printable-report { padding:44px; color:#122033; background:#fff; border-top:7px solid #2679e8; border-radius:4px; box-shadow:0 20px 60px rgba(0,0,0,.32); }
.tutor-printable-report > header { display:grid; grid-template-columns:86px minmax(0,1fr); gap:24px; align-items:center; padding-bottom:26px; border-bottom:2px solid #e2e9ef; }
.tutor-printable-report > header img { width:78px; height:78px; object-fit:cover; border-radius:18px; }
.tutor-printable-report > header span { color:#2679e8; font-size:12px; font-weight:900; letter-spacing:.16em; }
.tutor-printable-report > header h1 { margin:6px 0; font-size:29px; line-height:1.16; text-transform:uppercase; }
.tutor-printable-report > header p { margin:0; color:#718091; font-size:14px; text-transform:uppercase; }
.report-student-identity { display:grid; grid-template-columns:1.4fr 1fr 1fr; gap:20px; margin-top:24px; padding:22px; background:#f4f7fa; border:1px solid #dbe4eb; border-radius:16px; }
.report-student-identity small,.report-student-identity strong,.report-student-identity span { display:block; }
.report-student-identity small { color:#8b99a7; font-size:10px; font-weight:900; letter-spacing:.1em; }
.report-student-identity strong { margin-top:8px; font-size:18px; }
.report-student-identity span { margin-top:4px; color:#647485; font-size:12px; }
.report-metric-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:12px; margin-top:20px; }
.report-metric-grid article { padding:17px; border:1px solid #dbe4eb; border-radius:14px; }
.report-metric-grid span,.report-metric-grid strong,.report-metric-grid small { display:block; }
.report-metric-grid span { color:#8493a2; font-size:11px; font-weight:800; }
.report-metric-grid strong { margin-top:9px; color:#174e97; font-size:27px; }
.report-metric-grid small { margin-top:4px; color:#6e7c89; font-size:10px; }
.report-block { margin-top:26px; }
.report-block h2,.report-comment h2 { margin:0 0 12px; color:#7b8b9a; font-size:15px; letter-spacing:.1em; text-transform:uppercase; }
.report-block table { width:100%; border-collapse:collapse; overflow:hidden; border:1px solid #d8e2ea; border-radius:12px; }
.report-block th,.report-block td { padding:12px 13px; text-align:left; border-bottom:1px solid #e2e8ed; font-size:12px; }
.report-block th { color:#174e97; background:#edf5fc; font-weight:900; }
.report-empty { padding:16px; color:#738291; background:#f5f8fa; border-radius:11px; }
.report-comment { margin-top:26px; padding:20px; background:#f5f8fa; border-left:5px solid #2679e8; border-radius:12px; }
.report-comment p { margin:0; color:#28394a; line-height:1.65; }
.report-comment small { display:block; margin-top:10px; color:#758493; }
.tutor-printable-report > footer { display:flex; justify-content:space-between; gap:30px; margin-top:34px; padding-top:20px; border-top:2px solid #e2e9ef; }
.tutor-printable-report > footer strong,.tutor-printable-report > footer span { display:block; }
.tutor-printable-report > footer span { color:#748392; font-size:11px; }
.tutor-printable-report > footer div:last-child { min-width:180px; text-align:center; }
.tutor-printable-report > footer div:last-child strong { margin-top:24px; padding-top:8px; border-top:1px solid #9aa7b3; }
html[data-theme='light'] .tutor-report-launch,html[data-theme='light'] .tutor-report-toolbar { color:#102337; background:#fff; border-color:#cbdbe5; }
html[data-theme='light'] .tutor-report-toolbar input { color:#102337; background:#f8fbfd; border-color:#bfd2dd; }
@media(max-width:700px){.tutor-report-toolbar{align-items:stretch;flex-direction:column}.tutor-report-toolbar label{margin-left:0}.tutor-report-toolbar input{width:100%}.tutor-printable-report{padding:24px 18px}.tutor-printable-report>header{grid-template-columns:62px 1fr;gap:14px}.tutor-printable-report>header img{width:58px;height:58px}.tutor-printable-report>header h1{font-size:20px}.report-student-identity{grid-template-columns:1fr}.report-metric-grid{grid-template-columns:1fr 1fr}.report-block{overflow-x:auto}.report-block table{min-width:560px}.tutor-printable-report>footer{flex-direction:column}}
@media print{
  @page{size:A4;margin:12mm}
  body{background:#fff!important}
  .tutor-dashboard{max-width:none!important;padding:0!important;background:#fff!important}
  .tutor-dashboard-header,.tutor-report-toolbar,.tutor-bottom-navigation{display:none!important}
  .tutor-report-page{margin:0!important}
  .tutor-printable-report{padding:0!important;border-top:6px solid #2679e8!important;box-shadow:none!important}
  .tutor-printable-report,.tutor-printable-report *{print-color-adjust:exact;-webkit-print-color-adjust:exact}
  .report-block{break-inside:avoid}
  .report-comment{break-inside:avoid}
}

