.academic-quests-button { display:grid; grid-template-columns:48px minmax(0,1fr) 28px; gap:13px; align-items:center; width:100%; min-height:78px; margin-top:12px; padding:12px 14px; color:#f5fbff; text-align:left; background:linear-gradient(135deg,rgba(37,197,212,.2),rgba(10,23,36,.98)); border:1px solid rgba(37,197,212,.65); border-radius:18px; box-shadow:inset 0 1px 0 rgba(255,255,255,.04),0 12px 28px rgba(0,0,0,.18); cursor:pointer; }
