.journal-personal-progress > strong { color:var(--student-text,#f5f8fb); font-size:14px; }
.journal-personal-progress > p { margin:7px 0 0; color:var(--student-muted,#9bb0c0); font-size:13px; line-height:1.55; }
.learning-plan-section { margin-bottom:20px; }
