  font-size: clamp(17px, 5vw, 24px);
  font-weight: 800;
  letter-spacing: .04em;
}

.student-menu-button,
.student-refresh {
  width: 44px;
  height: 44px;
  padding: 0;
  color: #25c5d4;
  background: transparent;
