/* Theme control for every dashboard role */
.student-header-actions,
.dashboard-header-actions {
  display: flex;
  align-items: center;
  gap: 9px;
  flex: 0 0 auto;
}

.theme-switch {
  display: grid;
  grid-template-columns: repeat(2, auto);
  gap: 3px;
  padding: 3px;
  background: #0b1826;
  border: 1px solid #244054;
  border-radius: 999px;
}

.theme-switch button {
  min-width: 48px;
  min-height: 32px;
  padding: 6px 9px;
  color: #8194a5;
  background: transparent;
  border: 0;
  border-radius: 999px;
  cursor: pointer;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .04em;
}

.theme-switch button.active {
  color: #06111f;
  background: #25c5d4;
  box-shadow: 0 3px 10px rgba(37,197,212,.24);
}

.student-header-refresh {
  width: 44px;
  height: 44px;
  flex: 0 0 auto;
  color: #25c5d4;
  background: #0c1928;
  border: 1px solid #1d394a;
  border-radius: 14px;
  cursor: pointer;
  font-size: 27px;
}

