html[data-theme='light'] .student-main-menu,
html[data-theme='light'] .student-full-menu,
html[data-theme='light'] .student-detail-page,
html[data-theme='light'] .student-checkin-page,
html[data-theme='light'] .dashboard-page {
  color: #102337;
  background: #edf4f8;
}

html[data-theme='light'] .app-header,
html[data-theme='light'] .student-dashboard-header,
html[data-theme='light'] .student-menu-header,
html[data-theme='light'] .full-menu-header {
  background: rgba(237,244,248,.96);
  border-color: #c9d9e4;
}

html[data-theme='light'] .brand-small strong,
html[data-theme='light'] .student-dashboard-brand strong,
html[data-theme='light'] .student-greeting,
html[data-theme='light'] .student-greeting span,
html[data-theme='light'] .section-heading,
html[data-theme='light'] .page-heading,
html[data-theme='light'] .detail-panel h2,
html[data-theme='light'] .student-rank-card > h2,
html[data-theme='light'] .monthly-quests-title h2,
html[data-theme='light'] .scroll-report-cards strong {
  color: #102337;
}

