.tutor-student-list small,.tutor-journal-history small { margin-top:4px; overflow:hidden; color:#8194a4; font-size:11px; text-overflow:ellipsis; white-space:nowrap; }
.tutor-journal-form { display:grid; gap:15px; }
.tutor-journal-form label,.tutor-journal-form label > span { display:block; }
.tutor-journal-form label > span { margin-bottom:7px; color:#9eb0bd; font-size:11px; font-weight:800; }
.tutor-journal-form input,.tutor-journal-form select,.tutor-journal-form textarea { width:100%; padding:13px 14px; color:#eef5f8; background:#081521; border:1px solid #2b4253; border-radius:12px; font:inherit; outline:none; }
.tutor-journal-form input:focus,.tutor-journal-form select:focus,.tutor-journal-form textarea:focus { border-color:#25c5d4; }
.tutor-form-grid { display:grid; grid-template-columns:1fr 1fr; gap:12px; }
.tutor-journal-form > button { min-height:51px; color:#06111f; background:#25c5d4; border:0; border-radius:13px; cursor:pointer; font-weight:900; }
.tutor-academic-menu { display:grid; gap:12px; }
.tutor-academic-menu > button { display:grid; grid-template-columns:52px minmax(0,1fr) auto; gap:14px; align-items:center; width:100%; padding:17px; color:#eef5f8; text-align:left; background:#0b1724; border:1px solid #294152; border-radius:16px; cursor:pointer; }
