.eight-meeting-plan-grid article div { min-width:0; }
.eight-meeting-plan-grid article small { display:block; color:#22d3ee; font-size:9px; font-weight:900; letter-spacing:.08em; }
.eight-meeting-plan-grid article strong { display:block; margin-top:4px; color:var(--student-text,#f5f8fb); font-size:14px; }
