.eight-meeting-plan-grid article button { grid-column:1/-1; width:100%; margin-top:4px; padding:9px 10px; border:1px solid rgba(34,211,238,.24); border-radius:11px; background:rgba(34,211,238,.08); color:#22d3ee; font-size:11px; font-weight:800; }
.learning-activity-status { display:inline-flex; margin:9px 0; padding:5px 9px; border-radius:999px; background:rgba(34,211,238,.1); color:#22d3ee; font-size:10px; font-weight:900; letter-spacing:.05em; }
.journal-entry-card.direncanakan .learning-activity-status { background:rgba(250,204,21,.12); color:#facc15; }
.journal-entry-card.belum-diisi { opacity:.58; }
.journal-objective { color:var(--student-muted,#9bb0c0); font-size:13px; line-height:1.55; }
[data-theme="light"] .eight-meeting-plan-grid article { background:rgba(244,249,251,.9); }
@media(max-width:640px){.eight-meeting-plan-grid{grid-template-columns:1fr}}
[data-theme="light"] .journal-student-roster > article { background: rgba(238,249,252,.8); }
