}

/* LINKED LEARNING TARGET, ASSIGNMENT & CHALLENGE */
.linked-learning-package { border-color: rgba(250,204,21,.25); background: linear-gradient(145deg,rgba(250,204,21,.045),rgba(34,211,238,.025)); }
.linked-package-toggle { margin-top:14px; padding:15px; border:1px solid rgba(34,211,238,.2); border-radius:17px; background:rgba(5,18,31,.34); }
.linked-package-toggle > label { display:flex!important; flex-direction:row!important; align-items:center; gap:12px; cursor:pointer; }
.linked-package-toggle > label input { width:20px!important; height:20px; flex:0 0 auto; accent-color:#22d3ee; }
.linked-package-toggle > label span { display:flex; flex-direction:column; gap:3px; }
.linked-package-toggle > label strong { color:var(--student-text,#f5f8fb); font-size:15px; }
.linked-package-toggle > label small { color:var(--student-muted,#8fa7b9); font-size:12px; line-height:1.4; }
.linked-package-toggle.challenge-link { border-color:rgba(168,85,247,.28); }
.linked-package-fields { display:grid; gap:12px; margin-top:14px; padding-top:14px; border-top:1px solid rgba(143,167,185,.16); }
.learning-target-card { margin:8px 0 13px; padding:13px 14px; border-left:3px solid #facc15; border-radius:0 13px 13px 0; background:rgba(250,204,21,.075); }
.learning-target-card span { display:block; margin-bottom:5px; color:#facc15; font-size:10px; font-weight:900; letter-spacing:.11em; }
.learning-target-card p { margin:0; color:var(--student-text,#f5f8fb); font-size:13px; line-height:1.55; }
.learning-evidence-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:10px; margin-top:14px; }
.learning-evidence-grid button { min-width:0; padding:13px; border:1px solid rgba(34,211,238,.22); border-radius:14px; background:rgba(34,211,238,.065); color:inherit; text-align:left; cursor:pointer; }
.learning-evidence-grid button:last-child { border-color:rgba(168,85,247,.27); background:rgba(168,85,247,.07); }
.learning-evidence-grid span,.learning-evidence-grid strong,.learning-evidence-grid small { display:block; }
.learning-evidence-grid span { color:#22d3ee; font-size:9px; font-weight:900; letter-spacing:.11em; text-transform:uppercase; }
.learning-evidence-grid button:last-child span { color:#c084fc; }
.learning-evidence-grid strong { margin-top:5px; overflow:hidden; color:var(--student-text,#f5f8fb); font-size:13px; text-overflow:ellipsis; white-space:nowrap; }
.learning-evidence-grid small { margin-top:7px; color:var(--student-muted,#8fa7b9); font-size:11px; line-height:1.4; }
[data-theme="light"] .linked-package-toggle { background:rgba(240,248,251,.9); }
[data-theme="light"] .learning-target-card p,[data-theme="light"] .learning-evidence-grid strong { color:#102337; }
@media(max-width:560px){.learning-evidence-grid{grid-template-columns:1fr}}

/* ASSIGNMENT QUESTION BUILDER */
.assignment-question-builder { display:grid; gap:16px; }
.question-builder-heading { display:flex; align-items:center; justify-content:space-between; gap:16px; }
.question-builder-heading span,.question-builder-heading strong { display:block; }
.question-builder-heading span { color:#22d3ee; font-size:11px; font-weight:900; letter-spacing:.12em; }
.question-builder-heading strong { margin-top:5px; color:var(--student-text,#f5f8fb); font-size:16px; }
.question-builder-heading button { min-height:42px; padding:10px 15px; border:1px solid rgba(34,211,238,.35); border-radius:12px; background:rgba(34,211,238,.1); color:#22d3ee; font-weight:900; cursor:pointer; }
.assignment-question-builder > article { padding:17px; border:1px solid rgba(34,211,238,.22); border-radius:18px; background:rgba(5,18,31,.35); }
.assignment-question-builder article header { display:grid; grid-template-columns:1fr auto auto; align-items:center; gap:12px; margin-bottom:13px; }
.assignment-question-builder article header > b { color:var(--student-text,#f5f8fb); }
.assignment-question-builder article header label { display:flex!important; flex-direction:row!important; align-items:center; gap:7px; }
.assignment-question-builder article header label span { color:var(--student-muted,#8fa7b9); font-size:11px; }
.assignment-question-builder article header label input { width:68px!important; padding:8px!important; text-align:center; }
.assignment-question-builder article header > button { width:34px; height:34px; border:0; border-radius:10px; background:rgba(248,113,113,.12); color:#fb7185; font-size:20px; cursor:pointer; }
.assignment-question-builder textarea { width:100%; }
.question-option-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:9px; margin-top:12px; }
.question-option-grid label { display:grid!important; grid-template-columns:auto 28px minmax(0,1fr); align-items:center; gap:7px; padding:9px; border:1px solid rgba(143,167,185,.18); border-radius:12px; }
.question-option-grid label.correct-option { border-color:rgba(52,211,153,.45); background:rgba(52,211,153,.07); }
.question-option-grid label > input[type="radio"] { width:17px!important; height:17px; accent-color:#34d399; }
.question-option-grid label > span { display:grid; place-items:center; width:27px; height:27px; border-radius:8px; background:rgba(34,211,238,.1); color:#22d3ee; font-size:11px; font-weight:900; }
.question-option-grid label > input:last-child { min-width:0; padding:9px 10px!important; }
.assignment-question-builder article > small,.grading-mode-note { display:block; margin-top:10px; color:var(--student-muted,#8fa7b9); font-size:12px; line-height:1.5; }
.student-question-list { display:grid; gap:15px; margin-bottom:16px; }
.student-question-list fieldset { min-width:0; margin:0; padding:15px; border:1px solid rgba(34,211,238,.2); border-radius:16px; }
.student-question-list legend { display:grid; grid-template-columns:32px minmax(0,1fr) auto; align-items:start; gap:10px; width:100%; padding:0 5px 10px; }
.student-question-list legend span { display:grid; place-items:center; width:30px; height:30px; border-radius:9px; background:rgba(34,211,238,.12); color:#22d3ee; font-size:11px; font-weight:900; }
.student-question-list legend strong { color:var(--student-text,#f5f8fb); font-size:14px; line-height:1.5; }
.student-question-list legend b { color:#facc15; font-size:11px; white-space:nowrap; }
.student-question-list fieldset > label { display:grid; grid-template-columns:auto 30px minmax(0,1fr); align-items:center; gap:9px; margin-top:8px; padding:11px; border:1px solid rgba(143,167,185,.18); border-radius:12px; cursor:pointer; }
.student-question-list fieldset > label.selected { border-color:#22d3ee; background:rgba(34,211,238,.08); }
.student-question-list label input { width:18px!important; height:18px; accent-color:#22d3ee; }
.student-question-list label > span { color:#22d3ee; font-weight:900; }
.student-question-list label p { margin:0; color:var(--student-text,#f5f8fb); font-size:13px; line-height:1.45; }
[data-theme="light"] .assignment-question-builder > article { background:#f5fafc; }
[data-theme="light"] .assignment-question-builder article header > b,[data-theme="light"] .question-builder-heading strong,[data-theme="light"] .student-question-list legend strong,[data-theme="light"] .student-question-list label p { color:#102337; }
@media(max-width:650px){.question-builder-heading{align-items:stretch;flex-direction:column}.question-option-grid{grid-template-columns:1fr}.student-question-list legend{grid-template-columns:30px minmax(0,1fr)}.student-question-list legend b{grid-column:2}}

/* DETAILED MONTHLY ACADEMIC REPORT */
.report-analytics-grid { display:grid; grid-template-columns:1.25fr .75fr; gap:18px; margin:24px 0; }
.report-skill-panel,.report-overview-panel { padding:20px; border:1px solid #d8e2ea; border-radius:15px; background:#fff; }
.report-skill-panel h2 { margin:0 0 12px; color:#8293a4; font-size:14px; letter-spacing:.12em; text-transform:uppercase; }
.report-overview-panel { display:grid; gap:14px; }
.report-overview-panel > div { display:flex; flex-direction:column; padding:16px; border-radius:12px; background:#f5f8fa; }
.report-overview-panel span { color:#8191a1; font-size:11px; font-weight:900; letter-spacing:.1em; }
.report-overview-panel strong { margin:5px 0; color:#102337; font-size:32px; }
.report-overview-panel small { color:#667788; }
.report-wide-table { width:100%; overflow-x:auto; }
.report-wide-table table { min-width:900px; }
.report-cell-note { display:block; max-width:260px; margin-top:5px; color:#6f7f8e; font-weight:400; line-height:1.4; white-space:normal; }
.student-detailed-session-table { min-width:920px !important; }
.student-report-footer { display:flex; justify-content:space-between; gap:30px; margin-top:28px; padding:20px 4px 4px; border-top:2px solid #dfe8ef; color:#24384a; }
.student-report-footer strong,.student-report-footer span { display:block; }
.student-report-footer span { color:#7c8c9b; font-size:11px; }
.student-report-footer > div:last-child { min-width:170px; text-align:center; }
.student-report-footer > div:last-child strong { margin-top:22px; padding-top:7px; border-top:1px solid #9eabb6; }
@media(max-width:700px){.report-analytics-grid{grid-template-columns:1fr}.student-report-footer{flex-direction:column}}
@media print{
  .detailed-monthly-report .report-wide-table{overflow:visible!important}
  .detailed-monthly-report .report-wide-table table{min-width:0!important;font-size:9px}
  .detailed-monthly-report .report-wide-table th,.detailed-monthly-report .report-wide-table td{padding:7px 5px!important}
  .student-detailed-session-table{min-width:0!important}
  .student-report-footer{break-inside:avoid}
}

/* STUDENT MAIN MENU — tempel paling bawah src/index.css */
.student-main-menu {
