}

.student-dashboard-header { display:flex; align-items:center; justify-content:space-between; gap:14px; min-height:82px; border-bottom:1px solid #1b3041; }
.student-dashboard-brand { display:flex; align-items:center; gap:12px; min-width:0; }
.paper-plane-logo { display:grid; place-items:center; width:54px; height:54px; flex:0 0 54px; color:#20c5d6; filter:drop-shadow(0 6px 12px rgba(32,197,214,.24)); }
.paper-plane-logo svg { display:block; width:48px; height:48px; overflow:visible; fill:currentColor; }
.student-profile-photo { display:grid; place-items:center; width:52px; height:52px; flex:0 0 52px; overflow:hidden; color:#07111f; background:linear-gradient(145deg,#dffbff,#25c5d4); border:2px solid rgba(37,197,212,.7); border-radius:16px; font-size:16px; font-weight:900; }
.student-profile-photo img { width:100%; height:100%; object-fit:cover; object-position:center; }
.student-dashboard-brand strong,.student-dashboard-brand span { display:block; }
.student-dashboard-brand strong { color:#f7fafc; font-size:17px; }
.student-dashboard-brand span { margin-top:3px; color:#25c5d4; font-size:12px; font-weight:800; }
.student-dashboard-header > button { width:44px; height:44px; flex:0 0 auto; color:#25c5d4; background:#0c1928; border:1px solid #1d394a; border-radius:14px; font-size:27px; cursor:pointer; }

.student-bottom-navigation { position:fixed; left:50%; bottom:max(14px,env(safe-area-inset-bottom)); z-index:70; display:grid; grid-template-columns:repeat(4,1fr); width:min(540px,calc(100vw - 28px)); padding:8px; background:rgba(11,24,38,.96); border:1px solid rgba(83,112,133,.42); border-radius:22px; box-shadow:0 18px 48px rgba(0,0,0,.48); backdrop-filter:blur(18px); transform:translateX(-50%); }
.student-bottom-navigation button { min-width:0; min-height:58px; padding:7px 4px; color:#7f91a1; background:transparent; border:0; border-radius:15px; font-size:10px; font-weight:800; cursor:pointer; }
.student-bottom-navigation button span { display:block; margin-bottom:3px; font-size:21px; line-height:1; }
.student-bottom-navigation button.active { color:#25c5d4; background:rgba(37,197,212,.12); }
.student-full-menu,.student-detail-page { padding-bottom:116px; }

