.tutor-bottom-navigation { position:fixed; left:50%; bottom:max(14px,env(safe-area-inset-bottom)); z-index:80; display:grid; grid-template-columns:repeat(4,1fr); width:min(600px,calc(100vw - 28px)); padding:8px; background:rgba(11,24,38,.96); border:1px solid rgba(83,112,133,.42); border-radius:22px; box-shadow:0 18px 48px rgba(0,0,0,.48); backdrop-filter:blur(18px); transform:translateX(-50%); }
