.report-student-identity strong { margin-top:8px; font-size:18px; }
.report-student-identity span { margin-top:4px; color:#647485; font-size:12px; }
.report-metric-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:12px; margin-top:20px; }
.report-metric-grid article { padding:17px; border:1px solid #dbe4eb; border-radius:14px; }
.report-metric-grid span,.report-metric-grid strong,.report-metric-grid small { display:block; }
.report-metric-grid span { color:#8493a2; font-size:11px; font-weight:800; }
