.report-metric-grid small { margin-top:4px; color:#6e7c89; font-size:10px; }
.report-block { margin-top:26px; }
.report-block h2,.report-comment h2 { margin:0 0 12px; color:#7b8b9a; font-size:15px; letter-spacing:.1em; text-transform:uppercase; }
.report-block table { width:100%; border-collapse:collapse; overflow:hidden; border:1px solid #d8e2ea; border-radius:12px; }
.report-block th,.report-block td { padding:12px 13px; text-align:left; border-bottom:1px solid #e2e8ed; font-size:12px; }
