@media(max-width:700px){.tutor-report-toolbar{align-items:stretch;flex-direction:column}.tutor-report-toolbar label{margin-left:0}.tutor-report-toolbar input{width:100%}.tutor-printable-report{padding:24px 18px}.tutor-printable-report>header{grid-template-columns:62px 1fr;gap:14px}.tutor-printable-report>header img{width:58px;height:58px}.tutor-printable-report>header h1{font-size:20px}.report-student-identity{grid-template-columns:1fr}.report-metric-grid{grid-template-columns:1fr 1fr}.report-block{overflow-x:auto}.report-block table{min-width:560px}.tutor-printable-report>footer{flex-direction:column}}
