.journal-personal-progress > strong { color:var(--student-text,#f5f8fb); font-size:14px; }
.journal-personal-progress > p { margin:7px 0 0; color:var(--student-muted,#9bb0c0); font-size:13px; line-height:1.55; }
.learning-plan-section { margin-bottom:20px; }
.eight-meeting-plan-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:11px; margin-top:18px; }
.eight-meeting-plan-grid article { display:grid; grid-template-columns:44px 1fr; gap:12px; padding:14px; border:1px dashed rgba(143,167,185,.3); border-radius:16px; background:rgba(5,18,31,.28); }
