.registration-admin-page{padding:28px 0 100px}.registration-admin-list{display:grid;gap:18px}.registration-admin-list>article{padding:22px;background:#0b1b2d;border:1px solid #24465a;border-radius:20px}.registration-admin-list article>header{display:flex;justify-content:space-between;gap:16px}.registration-admin-list header small,.registration-admin-list header p{color:#91a8ba}.registration-admin-list header h3{margin:4px 0}.registration-admin-list header>span{align-self:flex-start;padding:7px 10px;color:#ffd66b;background:rgba(255,196,50,.12);border-radius:9px;font-size:11px;font-weight:900}.registration-contact{display:flex;flex-wrap:wrap;gap:10px 24px;margin:16px 0;padding:12px 0;border-block:1px solid #1d3547;color:#9db0c0}.registration-approval-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.registration-admin-list label{display:grid;gap:6px}.registration-admin-list label span{color:#8fa6b8;font-size:12px;font-weight:800}.registration-admin-list input{min-height:46px;padding:10px 12px;color:#fff;background:#071321;border:1px solid #29475b;border-radius:11px;font:inherit}.registration-note{margin-top:12px}.registration-admin-list footer{display:flex;justify-content:flex-end;gap:10px;margin-top:16px}.registration-admin-list footer button{min-height:44px;padding:9px 15px;border-radius:11px;font-weight:900;cursor:pointer}.registration-admin-list .reject{color:#ff9ba4;background:#2a1420;border:1px solid #713040}.registration-admin-list .approve{color:#05131d;background:#25c5d4;border:0}.registration-admin-list .approve:disabled{opacity:.45;cursor:not-allowed}
