/* Tutor Dashboard */
.tutor-dashboard { width:100%; max-width:900px; min-height:100vh; margin:0 auto; padding:0 20px 116px; color:#eef5f8; background:#07111f; }
.tutor-dashboard-header { display:flex; justify-content:space-between; gap:14px; align-items:center; min-height:88px; border-bottom:1px solid #1b3041; }
.tutor-refresh { width:44px; height:44px; color:#25c5d4; background:#0c1928; border:1px solid #1d394a; border-radius:14px; cursor:pointer; font-size:26px; }
.tutor-loading,.tutor-notice { margin-top:18px; padding:14px 16px; color:#a9bbc7; background:#0e1c2b; border:1px solid #294153; border-radius:14px; }
.tutor-welcome { margin-top:26px; padding:30px; background:linear-gradient(145deg,#0d2032,#0a1826); border:1px solid rgba(37,197,212,.38); border-radius:28px; }
.tutor-welcome > span { color:#39e2a0; font-size:11px; font-weight:900; }
.tutor-welcome h1 { margin:24px 0 12px; font-size:clamp(28px,7vw,44px); }
.tutor-welcome h1 strong { display:block; margin-top:6px; color:#25c5d4; }
.tutor-welcome p { margin:0; color:#91a7b7; line-height:1.6; }
.tutor-stat-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:12px; margin-top:20px; }
.tutor-stat-grid article { display:grid; padding:18px; background:#0d1927; border:1px solid #24394a; border-radius:18px; }
.tutor-stat-grid article > span { color:#25c5d4; font-size:22px; }
.tutor-stat-grid strong { margin-top:12px; font-size:29px; }
.tutor-stat-grid small { margin-top:4px; color:#8196a6; }
.tutor-section { margin-top:24px; padding:22px; background:#0c1826; border:1px solid #22394b; border-radius:24px; }
.tutor-page-section { min-height:calc(100vh - 220px); }
.tutor-section-heading { display:flex; justify-content:space-between; gap:16px; align-items:flex-end; margin-bottom:18px; }
.tutor-section-heading span { color:#25c5d4; font-size:10px; font-weight:900; letter-spacing:.12em; }
.tutor-section-heading h2 { margin:5px 0 0; font-size:24px; }
.tutor-section-heading button,.tutor-back { padding:9px 12px; color:#25c5d4; background:transparent; border:1px solid #285065; border-radius:10px; cursor:pointer; }
.tutor-class-list { display:grid; gap:12px; }
.tutor-class-card { display:grid; grid-template-columns:52px minmax(0,1fr) auto; gap:14px; align-items:center; width:100%; padding:16px; color:#f1f6f9; text-align:left; background:#101e2d; border:1px solid #2b4152; border-radius:17px; cursor:pointer; }
.tutor-class-icon { display:grid; place-items:center; width:52px; height:52px; color:#25c5d4; background:rgba(37,197,212,.1); border-radius:14px; font-size:22px; }
.tutor-class-card small,.tutor-class-card strong,.tutor-class-card p { display:block; }
.tutor-class-card small { color:#25c5d4; font-size:9px; font-weight:900; }
.tutor-class-card strong { margin-top:4px; font-size:17px; }
.tutor-class-card p { margin:5px 0 0; color:#8397a7; font-size:11px; }
.tutor-class-card > b { color:#94a8b7; font-size:11px; white-space:nowrap; }
.tutor-empty { padding:28px; color:#8499a8; text-align:center; background:#091522; border:1px dashed #2c4354; border-radius:16px; }
.tutor-class-title { margin-top:18px; padding:20px; background:linear-gradient(135deg,rgba(37,197,212,.15),#0a1724); border-radius:18px; }
.tutor-class-title span { color:#25c5d4; font-size:10px; font-weight:900; }
.tutor-class-title h2 { margin:7px 0; font-size:27px; }
.tutor-class-title p { margin:0; color:#8fa4b3; }
.tutor-student-list,.tutor-journal-history { display:grid; gap:9px; margin-top:18px; }
.tutor-student-list article,.tutor-student-list button,.tutor-journal-history article { display:grid; grid-template-columns:42px minmax(0,1fr) auto; gap:12px; align-items:center; width:100%; padding:13px; color:#eef5f8; text-align:left; background:#0b1724; border:1px solid #263a4a; border-radius:13px; }
.tutor-student-list button { cursor:pointer; }
.tutor-student-list button > b { color:#25c5d4; }
.tutor-student-list article > span,.tutor-student-list button > span,.tutor-journal-history article > span { display:grid; place-items:center; width:40px; height:40px; color:#25c5d4; background:rgba(37,197,212,.1); border-radius:11px; font-weight:900; }
.tutor-student-list strong,.tutor-student-list small,.tutor-journal-history strong,.tutor-journal-history small { display:block; }
.tutor-student-list small,.tutor-journal-history small { margin-top:4px; overflow:hidden; color:#8194a4; font-size:11px; text-overflow:ellipsis; white-space:nowrap; }
.tutor-journal-form { display:grid; gap:15px; }
.tutor-journal-form label,.tutor-journal-form label > span { display:block; }
.tutor-journal-form label > span { margin-bottom:7px; color:#9eb0bd; font-size:11px; font-weight:800; }
.tutor-journal-form input,.tutor-journal-form select,.tutor-journal-form textarea { width:100%; padding:13px 14px; color:#eef5f8; background:#081521; border:1px solid #2b4253; border-radius:12px; font:inherit; outline:none; }
.tutor-journal-form input:focus,.tutor-journal-form select:focus,.tutor-journal-form textarea:focus { border-color:#25c5d4; }
.tutor-form-grid { display:grid; grid-template-columns:1fr 1fr; gap:12px; }
.tutor-journal-form > button { min-height:51px; color:#06111f; background:#25c5d4; border:0; border-radius:13px; cursor:pointer; font-weight:900; }
.tutor-academic-menu { display:grid; gap:12px; }
.tutor-academic-menu > button { display:grid; grid-template-columns:52px minmax(0,1fr) auto; gap:14px; align-items:center; width:100%; padding:17px; color:#eef5f8; text-align:left; background:#0b1724; border:1px solid #294152; border-radius:16px; cursor:pointer; }
.tutor-academic-menu > button > span { display:grid; place-items:center; width:52px; height:52px; color:#25c5d4; background:rgba(37,197,212,.1); border-radius:14px; font-size:23px; }
.tutor-academic-menu strong,.tutor-academic-menu small { display:block; }
.tutor-academic-menu small { margin-top:5px; color:#8296a6; }
.tutor-academic-menu > button > b { color:#25c5d4; font-size:20px; }
.tutor-score-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:10px; }
.student-assignments-page { margin-top:22px; }
.assignment-page-heading { display:flex; gap:14px; align-items:center; padding:20px; background:#111c2a; border:1px solid rgba(243,73,103,.38); border-radius:20px; }
.assignment-page-heading > span { display:grid; place-items:center; width:52px; height:52px; color:#ff637b; background:rgba(243,73,103,.1); border-radius:15px; font-size:25px; }
.assignment-page-heading h2,.assignment-page-heading p { margin:0; }
.assignment-page-heading p { margin-top:5px; color:#8799a9; font-size:12px; }
.student-assignment-list { display:grid; gap:13px; margin-top:16px; }
.student-assignment-list article { padding:20px; background:#101a27; border:1px solid #2a3b4a; border-radius:19px; }
.assignment-title-row { display:flex; justify-content:space-between; gap:14px; align-items:flex-start; }
.assignment-title-row small { color:#25c5d4; font-size:9px; font-weight:900; }
.assignment-title-row h3 { margin:5px 0 0; font-size:20px; }
.assignment-title-row > b { padding:8px 10px; color:#ffe04b; background:rgba(180,145,20,.18); border-radius:10px; font-size:11px; white-space:nowrap; }
.student-assignment-list article > p { color:#9badb9; font-size:13px; line-height:1.6; }
.assignment-meta { display:flex; justify-content:space-between; gap:12px; padding-top:13px; border-top:1px solid #293846; color:#7f929f; font-size:11px; }
.assignment-meta strong { color:#f3a84c; }
.tutor-bottom-navigation { position:fixed; left:50%; bottom:max(14px,env(safe-area-inset-bottom)); z-index:80; display:grid; grid-template-columns:repeat(4,1fr); width:min(600px,calc(100vw - 28px)); padding:8px; background:rgba(11,24,38,.96); border:1px solid rgba(83,112,133,.42); border-radius:22px; box-shadow:0 18px 48px rgba(0,0,0,.48); backdrop-filter:blur(18px); transform:translateX(-50%); }
.tutor-bottom-navigation button { min-height:58px; padding:7px 4px; color:#7f91a1; background:transparent; border:0; border-radius:15px; cursor:pointer; font-size:10px; font-weight:800; }
.tutor-bottom-navigation button span { display:block; margin-bottom:3px; font-size:21px; }
.tutor-bottom-navigation button.active { color:#25c5d4; background:rgba(37,197,212,.12); }
.tutor-five-navigation { grid-template-columns:repeat(5,1fr); }
html[data-theme='light'] .tutor-dashboard { color:#102337; background:#edf4f8; }
html[data-theme='light'] .tutor-dashboard-header { border-color:#c9d9e4; }
html[data-theme='light'] .tutor-welcome,html[data-theme='light'] .tutor-section,html[data-theme='light'] .tutor-stat-grid article,html[data-theme='light'] .tutor-class-card,html[data-theme='light'] .tutor-class-title,html[data-theme='light'] .tutor-student-list article,html[data-theme='light'] .tutor-student-list button,html[data-theme='light'] .tutor-journal-history article { color:#102337; background:#fff; border-color:#cbdbe5; }
html[data-theme='light'] .tutor-journal-form input,html[data-theme='light'] .tutor-journal-form select,html[data-theme='light'] .tutor-journal-form textarea { color:#102337; background:#f8fbfd; border-color:#bfd2dd; }
html[data-theme='light'] .tutor-academic-menu > button,html[data-theme='light'] .assignment-page-heading,html[data-theme='light'] .student-assignment-list article { color:#102337; background:#fff; border-color:#cbdbe5; }
