@media(max-width:600px){.tutor-dashboard{padding-inline:14px}.tutor-dashboard-header .brand-small strong{font-size:14px}.tutor-stat-grid{grid-template-columns:repeat(3,1fr);gap:7px}.tutor-stat-grid article{padding:13px 9px}.tutor-stat-grid strong{font-size:23px}.tutor-stat-grid small{font-size:9px}.tutor-section{padding:16px}.tutor-class-card{grid-template-columns:44px minmax(0,1fr)}.tutor-class-icon{width:44px;height:44px}.tutor-class-card>b{grid-column:2}.tutor-form-grid,.tutor-score-grid{grid-template-columns:1fr}.assignment-meta{align-items:flex-start;flex-direction:column}}

/* Assignment and program challenge workflow */
.tutor-review-list { display:grid; gap:10px; margin-top:20px; }
.tutor-review-list h3 { margin:0 0 3px; font-size:17px; }
.tutor-review-list > button { display:flex; justify-content:space-between; gap:16px; align-items:center; width:100%; padding:15px; color:#eef5f8; text-align:left; background:#0b1724; border:1px solid #294152; border-radius:14px; cursor:pointer; }
.tutor-review-list strong,.tutor-review-list small { display:block; }
.tutor-review-list small { max-width:540px; margin-top:5px; overflow:hidden; color:#8296a6; font-size:11px; text-overflow:ellipsis; white-space:nowrap; }
.tutor-review-list b { color:#25c5d4; font-size:11px; white-space:nowrap; }
.student-submit-message { margin:14px 0; padding:12px 14px; color:#42e6a4; background:rgba(33,196,135,.1); border:1px solid rgba(66,230,164,.32); border-radius:12px; font-size:12px; }
.student-response-box { display:grid; gap:10px; margin-top:15px; }
.student-response-box textarea { width:100%; padding:13px 14px; resize:vertical; color:#edf5f8; background:#08131f; border:1px solid #304455; border-radius:12px; font:inherit; outline:none; }
.student-response-box textarea:focus { border-color:#25c5d4; box-shadow:0 0 0 3px rgba(37,197,212,.08); }
.student-response-box button { min-height:46px; color:#06111f; background:#25c5d4; border:0; border-radius:12px; cursor:pointer; font-weight:900; }
.student-response-box button:disabled { cursor:wait; opacity:.58; }
.submission-result { margin-top:15px; padding:13px 14px; background:rgba(44,142,255,.09); border:1px solid rgba(83,159,255,.3); border-radius:12px; }
.submission-result strong { color:#78b7ff; }
.submission-result p { margin:7px 0 0; color:#9fb1be; font-size:12px; line-height:1.55; }
.submission-result.reviewed { background:rgba(33,196,135,.1); border-color:rgba(66,230,164,.32); }
.submission-result.reviewed strong { color:#42e6a4; }
.active-challenges-section { margin-top:22px; padding:20px; background:#0d1927; border:1px solid rgba(37,197,212,.34); border-radius:22px; }
.student-challenge-list { display:grid; gap:13px; margin-top:16px; }
.student-challenge-list article { padding:20px; background:#0a1522; border:1px solid #2a3d4e; border-radius:18px; }
.student-challenge-list article > p { color:#9badb9; font-size:13px; line-height:1.6; }
html[data-theme='light'] .tutor-review-list > button,html[data-theme='light'] .student-assignment-list article,html[data-theme='light'] .active-challenges-section,html[data-theme='light'] .student-challenge-list article { color:#102337; background:#fff; border-color:#cbdbe5; }
html[data-theme='light'] .student-response-box textarea { color:#102337; background:#f7fafc; border-color:#bfd2dd; }
html[data-theme='light'] .submission-result { background:#eef6ff; }
html[data-theme='light'] .submission-result.reviewed { background:#ecfbf5; }
@media(max-width:600px){.tutor-review-list>button{align-items:flex-start;flex-direction:column}.tutor-review-list small{max-width:calc(100vw - 90px)}.active-challenges-section{padding:15px}.student-challenge-list article{padding:16px}.assignment-title-row{align-items:flex-start;flex-direction:column}.assignment-title-row>b{align-self:flex-start}}
.grading-settings { border-color:rgba(66,230,164,.32); }
.grading-settings .tutor-section-heading span { color:#42e6a4; }
.grading-help { display:block; padding:11px 13px; color:#91a7b7; background:rgba(37,197,212,.07); border-radius:10px; font-size:12px; line-height:1.5; }
html[data-theme='light'] .grading-help { color:#526b7c; background:#edf7fa; }

/* Tutor student progress */
.tutor-pending-review { display:grid; grid-template-columns:42px minmax(0,1fr) auto; gap:12px; align-items:center; width:100%; margin-top:18px; padding:14px 16px; color:#eef5f8; text-align:left; background:rgba(243,168,76,.09); border:1px solid rgba(243,168,76,.34); border-radius:15px; cursor:pointer; }
.tutor-pending-review > span { display:grid; place-items:center; width:38px; height:38px; color:#07111f; background:#f3a84c; border-radius:12px; font-weight:900; }
.tutor-pending-review strong,.tutor-pending-review small { display:block; }
.tutor-pending-review small { margin-top:4px; color:#9badb9; font-size:12px; }
.tutor-pending-review > b { color:#f3a84c; }
.tutor-student-profile { display:grid; grid-template-columns:76px minmax(0,1fr) auto; gap:16px; align-items:center; margin-top:18px; padding:20px; background:linear-gradient(135deg,rgba(37,197,212,.14),#0a1724); border:1px solid rgba(37,197,212,.3); border-radius:20px; }
.tutor-student-avatar { display:grid; place-items:center; width:76px; height:76px; overflow:hidden; color:#06111f; background:linear-gradient(145deg,#85e7ef,#25c5d4); border-radius:20px; font-size:22px; font-weight:900; }
.tutor-student-avatar img { width:100%; height:100%; object-fit:cover; }
.tutor-student-profile small { color:#25c5d4; font-size:11px; font-weight:900; letter-spacing:.08em; }
.tutor-student-profile h2 { margin:5px 0; font-size:24px; }
.tutor-student-profile p { margin:0; color:#8ea3b2; font-size:13px; }
.tutor-student-profile > button { padding:11px 13px; color:#25c5d4; background:#091522; border:1px solid #285065; border-radius:11px; cursor:pointer; font-weight:800; }
.tutor-progress-summary { display:grid; grid-template-columns:repeat(4,1fr); gap:10px; margin-top:16px; }
.tutor-progress-summary article { display:grid; padding:15px; background:#0b1724; border:1px solid #263a4a; border-radius:15px; }
.tutor-progress-summary span { color:#8296a6; font-size:11px; }
.tutor-progress-summary strong { margin-top:8px; font-size:24px; }
.tutor-progress-summary small { margin-top:3px; color:#25c5d4; font-size:11px; }
.tutor-progress-grid { display:grid; grid-template-columns:1fr 1fr; gap:13px; margin-top:16px; }
.tutor-progress-panel { padding:17px; background:#0b1724; border:1px solid #263a4a; border-radius:17px; }
.tutor-progress-panel h3 { margin:0 0 12px; font-size:16px; }
.tutor-progress-panel > article { display:flex; justify-content:space-between; gap:12px; align-items:center; padding:11px 0; border-top:1px solid #223442; }
.tutor-progress-panel strong,.tutor-progress-panel small { display:block; }
.tutor-progress-panel small { margin-top:3px; color:#8296a6; font-size:11px; }
.tutor-progress-panel b { color:#25c5d4; font-size:11px; white-space:nowrap; }
.tutor-progress-panel .status-present { color:#42e6a4; }
.tutor-progress-panel .status-absent { color:#ff637b; }
.tutor-progress-panel > p { color:#8296a6; font-size:13px; }
.tutor-latest-note { margin-top:16px; padding:18px; background:rgba(137,92,246,.08); border:1px solid rgba(167,122,255,.28); border-radius:17px; }
.tutor-latest-note span { color:#b991ff; font-size:10px; font-weight:900; letter-spacing:.1em; }
.tutor-latest-note p { margin:10px 0; color:#dce6ec; line-height:1.6; }
.tutor-latest-note small { color:#8599a8; }
html[data-theme='light'] .tutor-pending-review,html[data-theme='light'] .tutor-student-profile,html[data-theme='light'] .tutor-progress-summary article,html[data-theme='light'] .tutor-progress-panel,html[data-theme='light'] .tutor-latest-note { color:#102337; background:#fff; border-color:#cbdbe5; }
html[data-theme='light'] .tutor-latest-note p { color:#294255; }
@media(max-width:700px){.tutor-student-profile{grid-template-columns:64px minmax(0,1fr)}.tutor-student-avatar{width:64px;height:64px}.tutor-student-profile>button{grid-column:1/-1}.tutor-progress-summary{grid-template-columns:1fr 1fr}.tutor-progress-grid{grid-template-columns:1fr}}

/* Tutor attendance control */
