/* LEARNING JOURNAL — CLASS ROSTER & ASSISTED COMMENTS */
.journal-roster-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 18px;
  margin-top: 12px;
  padding-top: 24px;
  border-top: 1px solid var(--student-line, rgba(34, 211, 238, .22));
}
.journal-roster-heading span { color: #22d3ee; font-size: 11px; font-weight: 800; letter-spacing: .14em; }
.journal-roster-heading h3 { margin: 5px 0; font-size: 24px; }
.journal-roster-heading small { color: var(--student-muted, #8fa7b9); line-height: 1.5; }
.journal-roster-actions { display: flex; gap: 9px; flex-wrap: wrap; justify-content: flex-end; }
.journal-roster-actions button {
  width: auto !important; padding: 10px 14px !important; border-radius: 12px !important;
  border: 1px solid rgba(34,211,238,.3) !important; background: rgba(34,211,238,.08) !important;
