/* STUDENT TUITION — INVOICE, PAYMENT HISTORY & PRINTABLE RECEIPT */
.tuition-page { display:grid; gap:20px; width:min(760px,100%); margin:0 auto 110px; }
.tuition-alert { display:flex; align-items:flex-start; gap:14px; padding:18px 20px; border:1px solid rgba(245,158,11,.42); border-radius:18px; color:#f8d17b; background:rgba(245,158,11,.09); }
.tuition-alert > span { display:grid; place-items:center; flex:0 0 36px; width:36px; height:36px; border-radius:50%; color:#081522; background:#f5b82e; font-weight:950; }
.tuition-alert strong,.tuition-alert p { display:block; }
.tuition-alert p { margin:5px 0 0; color:var(--student-muted,#9bb1c2); line-height:1.5; }
.tuition-document { overflow:hidden; color:#101b2e; background:#fff; border-radius:24px; box-shadow:0 22px 55px rgba(0,0,0,.22); }
.tuition-document > header { display:flex; align-items:flex-start; justify-content:space-between; gap:24px; padding:28px 32px; color:#fff; background:linear-gradient(135deg,#12398d,#2463dd); }
.tuition-document > header div { display:flex; flex-direction:column; }
.tuition-document > header div:last-child { text-align:right; }
.tuition-document > header span { font-size:12px; font-weight:900; letter-spacing:.16em; }
.tuition-document > header strong { margin-top:6px; font-size:15px; letter-spacing:.08em; }
.tuition-document > header b { font-size:22px; }
.tuition-document > header small { margin-top:4px; color:#c9dbff; }
.tuition-amount { display:flex; flex-direction:column; align-items:center; padding:36px 28px 30px; text-align:center; border-bottom:1px solid #e5eaf0; }
.tuition-amount span { color:#69788a; font-size:13px; font-weight:900; letter-spacing:.1em; }
.tuition-amount strong { margin:10px 0 4px; color:#0b1528; font-size:clamp(38px,8vw,60px); line-height:1; }
.tuition-amount small { color:#8794a2; }
.tuition-student-info { margin:28px 32px 20px; padding:22px 24px; background:#f5f7fa; border:1px solid #e0e6ed; border-radius:14px; }
.tuition-student-info > span { display:block; margin-bottom:12px; color:#2463d8; font-size:12px; font-weight:950; letter-spacing:.12em; }
.tuition-student-info strong { display:block; font-size:23px; }
.tuition-student-info p { margin:7px 0 0; color:#667486; line-height:1.5; }
.tuition-transaction { margin:0 32px 30px; }
.tuition-transaction > div { display:grid; grid-template-columns:minmax(120px,.75fr) minmax(0,1fr); gap:20px; padding:15px 0; border-bottom:1px solid #e7ebf0; }
.tuition-transaction > div:last-child { border-bottom:0; }
.tuition-transaction span { color:#6c7988; }
.tuition-transaction strong { text-align:right; overflow-wrap:anywhere; }
.tuition-transaction .paid { color:#0ba160; }
.tuition-transaction .unpaid { color:#dc4f4f; }
.receipt-thanks { margin:22px 32px 30px; color:#627083; font-style:italic; text-align:center; }
.tuition-document > footer { display:flex; align-items:center; justify-content:space-between; gap:16px; padding:22px 32px; color:#fff; background:#225ed5; }
.tuition-document > footer strong,.tuition-document > footer span { display:block; }
.tuition-document > footer span { color:#d9e5ff; font-size:11px; text-align:right; }
.tuition-actions { display:flex; gap:12px; flex-wrap:wrap; }
.tuition-actions a,.tuition-actions button,.receipt-print-button,.receipt-back-button { min-height:50px; padding:13px 18px; border:1px solid rgba(34,211,238,.35); border-radius:14px; font:inherit; font-weight:850; cursor:pointer; }
.tuition-actions a { flex:1 1 250px; color:#071522; background:#22d3ee; text-align:center; text-decoration:none; }
.tuition-actions button,.receipt-print-button,.receipt-back-button { color:#22d3ee; background:#0c1c2c; }
.tuition-actions > span { flex:1 1 100%; padding:15px 18px; color:var(--student-muted,#9bb1c2); border:1px dashed rgba(34,211,238,.25); border-radius:14px; }
.payment-history-section { padding:24px; border:1px solid rgba(34,211,238,.25); border-radius:24px; background:rgba(10,27,42,.7); }
.payment-history-heading { display:flex; align-items:center; gap:14px; margin-bottom:18px; }
.payment-history-heading > span { display:grid; place-items:center; width:44px; height:44px; border-radius:14px; color:#062117; background:#2fd195; font-size:24px; font-weight:950; }
.payment-history-heading h2,.payment-history-heading p { margin:0; }
.payment-history-heading p { margin-top:4px; color:var(--student-muted,#9bb1c2); }
.student-payment-history { display:grid; gap:11px; }
.student-payment-history button { display:grid; grid-template-columns:minmax(0,1fr) auto auto; align-items:center; gap:15px; width:100%; padding:17px 18px; color:inherit; text-align:left; border:1px solid rgba(34,211,238,.18); border-radius:16px; background:rgba(4,16,28,.55); cursor:pointer; }
.student-payment-history button span,.student-payment-history button b,.student-payment-history button small { display:block; }
.student-payment-history button small { margin-top:4px; color:var(--student-muted,#9bb1c2); }
.student-payment-history button > strong { color:#f3f7fa; white-space:nowrap; }
.student-payment-history button i { color:#2fd195; font-size:11px; font-style:normal; font-weight:950; white-space:nowrap; }
.receipt-back-button { justify-self:start; }
.receipt-print-button { justify-self:center; min-width:240px; color:#071522; background:#22d3ee; }
html[data-theme='light'] .tuition-alert p,html[data-theme='light'] .tuition-actions>span,html[data-theme='light'] .payment-history-heading p,html[data-theme='light'] .student-payment-history button small { color:#687b8b; }
html[data-theme='light'] .payment-history-section { background:#fff; border-color:#c8dce7; }
html[data-theme='light'] .student-payment-history button { color:#14283a; background:#f5f9fb; border-color:#d4e2e9; }
html[data-theme='light'] .student-payment-history button>strong { color:#14283a; }
@media(max-width:560px){
  .tuition-document>header,.tuition-document>footer { padding:22px 20px; }
  .tuition-document>header b { font-size:18px; }
  .tuition-student-info { margin:22px 20px 16px; padding:18px; }
  .tuition-transaction { margin:0 20px 24px; }
  .tuition-transaction>div { grid-template-columns:1fr; gap:5px; }
  .tuition-transaction strong { text-align:left; }
  .tuition-document>footer { align-items:flex-start; flex-direction:column; }
  .tuition-document>footer span { text-align:left; }
  .payment-history-section { padding:18px; }
  .student-payment-history button { grid-template-columns:1fr auto; }
  .student-payment-history button>i { grid-column:1/-1; }
}
@media print {
  @page { size:A4 portrait; margin:12mm; }
  body * { visibility:hidden!important; }
  #tuition-print-document,#tuition-print-document * { visibility:visible!important; }
  #tuition-print-document { position:absolute!important; inset:0 auto auto 0!important; width:100%!important; max-width:none!important; margin:0!important; color:#101b2e!important; background:#fff!important; border-radius:0!important; box-shadow:none!important; }
  #tuition-print-document>header { color:#fff!important; background:#174cae!important; }
  #tuition-print-document .tuition-student-info { background:#f5f7fa!important; }
  #tuition-print-document>footer { color:#fff!important; background:#225ed5!important; }
  #tuition-print-document,#tuition-print-document * { -webkit-print-color-adjust:exact!important; print-color-adjust:exact!important; }
  .tuition-actions,.receipt-print-button,.receipt-back-button,.student-bottom-navigation,.student-detail-page>header { display:none!important; }
}

/* STUDENT MAIN MENU — tempel paling bawah src/index.css */
.student-main-menu {
