.home-today-summary { margin-top:25px; text-align:left; }
.today-summary-heading { margin-bottom:16px; }
.today-summary-heading span { color:#25c5d4; font-size:10px; font-weight:900; letter-spacing:.13em; }
.today-summary-heading h2 { margin:7px 0 0; color:#f7fafc; font-size:clamp(24px,6vw,34px); }
.today-action-list { display:grid; gap:12px; }
.today-action-card { display:grid; grid-template-columns:52px minmax(0,1fr) 26px; gap:14px; align-items:center; width:100%; min-height:100px; padding:16px; color:#f7fafc; text-align:left; background:#0b1724; border:1px solid #294052; border-radius:19px; cursor:pointer; }
.today-action-card > i { display:grid; place-items:center; width:52px; height:52px; background:rgba(37,197,212,.12); border-radius:15px; font-size:25px; font-style:normal; }
.today-action-card span,.today-action-card strong,.today-action-card small { display:block; }
.today-action-card span { color:#25c5d4; font-size:11px; font-weight:900; letter-spacing:.08em; text-transform:uppercase; }
.today-action-card strong { margin-top:5px; overflow:hidden; font-size:16px; text-overflow:ellipsis; white-space:nowrap; }
.today-action-card small { margin-top:5px; color:#8496a6; line-height:1.35; }
.today-action-card > b { color:#25c5d4; font-size:23px; }
.today-action-card.urgent { background:linear-gradient(135deg,rgba(164,44,62,.28),#101824); border-color:rgba(255,113,128,.55); }
.today-action-card.urgent > i { background:rgba(255,113,128,.16); }
.today-action-card.urgent span,.today-action-card.urgent > b { color:#ff8b98; }
.today-action-card.warning { border-color:rgba(241,181,49,.52); }
.today-action-card.warning span,.today-action-card.warning > b { color:#f1c34c; }
.student-status-area { display:grid; gap:22px; margin-top:25px; text-align:left; }
.student-rank-card { padding:28px 22px; text-align:center; background:linear-gradient(145deg,#151c28,#0d1520); border:1px solid #465363; border-radius:27px; box-shadow:0 18px 44px rgba(0,0,0,.24); }
.rank-brand { display:block; color:#98a3b0; font-size:12px; font-weight:900; letter-spacing:.16em; text-align:right; }
.rank-emblem { position:relative; display:grid; place-items:center; width:116px; height:116px; margin:8px auto 35px; border:8px solid #3e4b59; border-radius:50%; }
.rank-emblem > span { display:grid; place-items:center; width:58px; height:68px; color:#fff; border:6px solid #fff; border-radius:24px 24px 30px 30px; font-size:31px; font-weight:900; }
.rank-emblem > small { position:absolute; bottom:-24px; padding:6px 25px; color:#fff; background:#080d16; border:2px solid #3f4b59; border-radius:999px; font-size:13px; font-weight:900; letter-spacing:.14em; }
.student-rank-card > p { margin:0; color:#a0a9b5; font-size:12px; font-weight:900; letter-spacing:.12em; text-transform:uppercase; }
.student-rank-card > h2 { margin:13px 0 24px; color:#e7ecf2; font-size:clamp(34px,9vw,53px); line-height:1.05; }
.exp-progress { height:22px; overflow:hidden; background:#172432; border:2px solid #465362; border-radius:999px; }
.exp-progress > span { display:block; height:100%; background:linear-gradient(90deg,#dce4ec,#aebac6); border-radius:inherit; transition:width .35s ease; }
.exp-meta { display:flex; justify-content:space-between; gap:15px; align-items:center; margin-top:15px; }
.exp-meta strong { color:#fff; font-size:14px; }
.exp-meta span { color:#788594; font-size:12px; font-weight:800; text-align:right; }
.exp-source-grid { display:grid; grid-template-columns:repeat(2,1fr); gap:9px; margin-top:22px; text-align:left; }
.exp-source-grid div { padding:12px; background:#0b131e; border:1px solid #303d4c; border-radius:12px; }
.exp-source-grid span,.exp-source-grid strong { display:block; }
.exp-source-grid span { overflow:hidden; color:#7f8c99; font-size:10px; font-weight:800; text-overflow:ellipsis; white-space:nowrap; }
.exp-source-grid strong { margin-top:6px; color:#dfe7ef; font-size:17px; }
.exp-source-grid strong::after { content:' EXP'; color:#657382; font-size:9px; }
.student-rank-card .view-quests-button { display:grid; grid-template-columns:48px minmax(0,1fr) 28px; gap:13px; align-items:center; width:100%; min-height:78px; margin-top:22px; padding:12px 14px; color:#f5fbff; text-align:left; background:linear-gradient(135deg,rgba(37,197,212,.17),rgba(10,23,36,.96)); border:1px solid rgba(37,197,212,.6); border-radius:18px; box-shadow:inset 0 1px 0 rgba(255,255,255,.04),0 12px 28px rgba(0,0,0,.18); cursor:pointer; transition:transform .18s ease,border-color .18s ease,background .18s ease; }
.student-rank-card .view-quests-button:hover { background:linear-gradient(135deg,rgba(37,197,212,.24),#0b1a29); border-color:#25c5d4; transform:translateY(-1px); }
.student-rank-card .view-quests-button:active { transform:translateY(1px); }
.view-quests-icon { display:grid; place-items:center; width:48px; height:48px; background:rgba(37,197,212,.14); border:1px solid rgba(37,197,212,.35); border-radius:14px; font-size:23px; }
.view-quests-copy,.view-quests-copy strong,.view-quests-copy small { display:block; min-width:0; }
.view-quests-copy strong { color:#39dbe8; font-size:15px; }
.view-quests-copy small { margin-top:5px; overflow:hidden; color:#8598a8; font-size:11px; font-weight:700; text-overflow:ellipsis; white-space:nowrap; }
.view-quests-arrow { color:#39dbe8; font-size:25px; font-weight:900; text-align:right; }
.academic-quests-button { display:grid; grid-template-columns:48px minmax(0,1fr) 28px; gap:13px; align-items:center; width:100%; min-height:78px; margin-top:12px; padding:12px 14px; color:#f5fbff; text-align:left; background:linear-gradient(135deg,rgba(37,197,212,.2),rgba(10,23,36,.98)); border:1px solid rgba(37,197,212,.65); border-radius:18px; box-shadow:inset 0 1px 0 rgba(255,255,255,.04),0 12px 28px rgba(0,0,0,.18); cursor:pointer; }
.academic-quests-button:hover { border-color:#25c5d4; transform:translateY(-1px); }
.academic-exp-breakdown { margin-top:20px; }
html[data-theme='light'] .academic-quests-button { color:#102337; background:linear-gradient(135deg,rgba(37,197,212,.18),#fff); }
.monthly-quests-card { padding:22px; background:#121c29; border:1px solid rgba(37,197,212,.42); border-radius:24px; }
.challenge-monthly-quests { margin-top:22px; }
.monthly-quests-title { display:flex; gap:13px; align-items:center; padding:5px 3px 20px; border-bottom:1px solid #2b3948; }
.monthly-quests-title > span { color:#ff7180; font-size:30px; }
.monthly-quests-title h2 { margin:0; font-size:22px; }
.monthly-quests-title small { color:#aab4bf; font-size:.72em; }
.quest-item { display:grid; grid-template-columns:58px minmax(0,1fr); gap:14px; margin-top:22px; padding:18px; background:#171e2a; border:1px solid #465161; border-radius:19px; }
.quest-item.done { background:rgba(22,145,111,.13); border-color:rgba(57,226,160,.5); }
.quest-icon { display:grid; place-items:center; width:58px; height:58px; color:#39e2a0; background:rgba(57,226,160,.1); border-radius:15px; font-size:29px; }
.quest-name { display:flex; justify-content:space-between; gap:12px; align-items:flex-start; }
.quest-name strong { color:#39e2a0; font-size:17px; }
.quest-name b { padding:7px 9px; color:#ffe14a; background:rgba(177,147,22,.22); border-radius:9px; font-size:12px; white-space:nowrap; }
.quest-content > p { margin:9px 0 15px; color:#9ba7b3; font-size:13px; line-height:1.5; }
.quest-progress-row { display:grid; grid-template-columns:1fr auto; gap:12px; align-items:center; }
.quest-progress-row > div { height:10px; overflow:hidden; background:#283545; border-radius:999px; }
.quest-progress-row > div span { display:block; height:100%; background:#39e2a0; border-radius:inherit; }
.quest-progress-row > strong { color:#39e2a0; font-size:12px; }
@media (max-width:480px) {
  .exp-meta { align-items:flex-start; flex-direction:column; }
  .exp-meta span { text-align:left; }
  .quest-item { grid-template-columns:46px minmax(0,1fr); padding:15px; }
  .quest-icon { width:46px; height:46px; }
  .quest-name { gap:8px; }
  .quest-name strong { font-size:15px; }
}
.academic-overview-detail { margin-top:22px; }
.academic-summary-cards { padding-bottom:18px; }
.academic-overview-hero h2 { margin:0; font-size:clamp(27px,7vw,39px); }
.academic-overview-hero > p { margin:13px 0 27px; color:#aec1d7; font-size:clamp(15px,4vw,20px); }
.overview-four-grid { display:grid; grid-template-columns:repeat(2,1fr); gap:22px 18px; }
.overview-four-grid span,.overview-four-grid strong { display:block; }
.overview-four-grid span { overflow:hidden; color:#88a2c0; font-size:10px; font-weight:800; letter-spacing:.08em; text-overflow:ellipsis; white-space:nowrap; }
.overview-four-grid strong { overflow:hidden; margin-top:8px; font-size:clamp(16px,4.5vw,22px); text-overflow:ellipsis; white-space:nowrap; }
.overview-actions { display:grid; grid-template-columns:repeat(2,1fr); gap:10px; margin-top:27px; }
.overview-actions button { min-height:64px; padding:12px; color:#07111f; background:#20d4f2; border:0; border-radius:15px; cursor:pointer; font-size:15px; font-weight:800; }
.overview-actions button:last-child { color:#25c5d4; background:#162334; border:1px solid rgba(37,197,212,.65); }
.scroll-report-cards { display:grid; gap:14px; margin-top:25px; }
.scroll-report-cards > button { display:flex; justify-content:space-between; gap:18px; align-items:center; width:100%; min-height:155px; padding:24px; color:#fff; text-align:left; background:#101925; border:1px solid #263546; border-top:5px solid #20d4f2; border-radius:20px; cursor:pointer; }
.scroll-report-cards span,.scroll-report-cards strong,.scroll-report-cards small { display:block; }
.scroll-report-cards span { color:#8c9cab; font-size:15px; }
.scroll-report-cards strong { margin:9px 0; font-size:32px; }
.scroll-report-cards .report-text-value { font-size:20px; }
.scroll-report-cards small { color:#6f8192; font-size:13px; }
.scroll-report-cards i { display:grid; place-items:center; flex:0 0 67px; width:67px; height:67px; border-radius:17px; font-size:30px; font-style:normal; }
.scroll-report-cards i.green { background:#15bf89; }
.scroll-report-cards i.red { background:#f33f65; }
.scroll-report-cards i.purple { background:#a546ef; }
.scroll-report-cards i.blue { background:#5061ed; }
.scroll-report-cards i.yellow { background:#e7a92f; }
.scroll-report-cards i.teal { background:#109caf; }

/* Daily Speaking Challenge */
.challenge-panel { text-align:center; }
.challenge-panel > h2 { margin-bottom:8px; font-size:clamp(25px,7vw,36px); }
.challenge-panel > p { margin:0 auto; max-width:520px; line-height:1.7; }
.challenge-target { margin:30px 0 24px; padding:28px 18px; background:#080f1b; border:1px solid #344356; border-radius:20px; }
.challenge-target small,.challenge-target strong { display:block; }
.challenge-target small { color:#8394a6; font-size:11px; font-weight:800; letter-spacing:.15em; }
.challenge-target strong { margin-top:23px; color:#fff; font-size:clamp(31px,9vw,48px); font-style:italic; }
.challenge-mic { display:grid; place-items:center; width:112px; height:112px; margin:0 auto; color:#06111f; background:#20d4f2; border:8px solid #07111f; border-radius:50%; box-shadow:0 0 30px rgba(32,212,242,.28); font-size:45px; }
.challenge-mic:disabled { cursor:not-allowed; opacity:.72; }
.challenge-panel .challenge-note { margin-top:18px; color:#7d91a3; font-size:12px; }
.challenge-program-action { display:grid; grid-template-columns:72px minmax(0,1fr); gap:16px; align-items:center; width:100%; max-width:460px; margin:24px auto 0; padding:17px; color:#eefaff; text-align:left; background:linear-gradient(135deg,rgba(37,197,212,.2),#0a1522); border:1px solid rgba(37,197,212,.58); border-radius:20px; }
.challenge-program-action > span { display:grid; place-items:center; width:72px; height:72px; color:#06111f; background:#20d4f2; border-radius:18px; font-size:27px; font-weight:900; }
.challenge-program-action > strong { font-size:17px; line-height:1.35; }
.challenge-program-action:disabled { cursor:not-allowed; opacity:.78; }

.learning-journal-section { display:grid; gap:16px; margin-top:22px; }
.journal-heading,.badges-title { display:flex; gap:14px; align-items:center; padding:20px; background:#111c2a; border:1px solid rgba(37,197,212,.38); border-radius:20px; }
.journal-heading > span,.badges-title > span { display:grid; place-items:center; width:52px; height:52px; flex:0 0 52px; color:#25c5d4; background:rgba(37,197,212,.1); border-radius:15px; font-size:25px; }
.journal-heading h2,.journal-heading p,.badges-title h2,.badges-title p { margin:0; }
.journal-heading h2,.badges-title h2 { color:#f4f8fb; font-size:22px; }
.journal-heading p,.badges-title p { margin-top:5px; color:#8799a9; font-size:12px; line-height:1.45; }
.journal-entry-card { display:grid; grid-template-columns:58px minmax(0,1fr); gap:18px; padding:22px; background:#0d1623; border:1px solid rgba(37,197,212,.35); border-radius:22px; }
.journal-number { display:grid; place-items:center; width:54px; height:54px; color:#25c5d4; background:rgba(37,197,212,.09); border:1px solid rgba(37,197,212,.4); border-radius:50%; font-size:14px; font-weight:900; }
.journal-entry-title { display:flex; justify-content:space-between; gap:15px; align-items:flex-start; }
.journal-entry-title h3 { margin:0; color:#fff; font-size:21px; }
.journal-entry-title time { color:#8493a1; font-size:12px; white-space:nowrap; }
.journal-tutor { margin:8px 0 17px; color:#25c5d4; font-size:13px; font-weight:700; }
.journal-activity { margin:0; padding-top:17px; color:#aab6c0; border-top:1px solid #283544; font-size:14px; line-height:1.65; }
.journal-activity strong { color:#eaf1f6; }

.badges-section { margin-top:24px; padding:20px; background:#111a27; border:1px solid rgba(160,80,237,.42); border-radius:24px; }
.badges-title { padding:0 0 18px; background:transparent; border:0; border-bottom:1px solid #2a3543; border-radius:0; }
.badges-title > span { color:#c272ff; background:rgba(174,83,241,.1); }
.badges-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:12px; margin-top:20px; }
.badge-card { display:flex; min-height:184px; padding:17px 10px; align-items:center; flex-direction:column; justify-content:flex-start; text-align:center; background:#171e29; border:1px solid #303b49; border-radius:18px; }
.badge-card.locked { filter:saturate(.25); opacity:.43; }
.badge-card.unlocked { background:rgba(28,150,118,.14); border-color:rgba(57,226,160,.48); box-shadow:inset 0 0 24px rgba(57,226,160,.05); }
.badge-icon { display:grid; place-items:center; width:58px; height:58px; color:#8793a0; background:#222c3a; border-radius:16px; font-size:27px; }
.badge-card.unlocked .badge-icon { color:#39e2a0; background:rgba(57,226,160,.12); }
.badge-card > strong { margin-top:14px; color:#e8eef4; font-size:13px; line-height:1.25; text-transform:uppercase; }
.badge-card > small { margin-top:8px; color:#788695; font-size:10px; line-height:1.35; }
.badge-card > b { margin-top:auto; padding-top:12px; color:#667482; font-size:9px; letter-spacing:.08em; }
.badge-card.unlocked > b { color:#39e2a0; }

html[data-theme='light'] .journal-heading,
html[data-theme='light'] .journal-entry-card,
html[data-theme='light'] .badges-section,
html[data-theme='light'] .badge-card { background:#fff; border-color:#cbdbe5; }
html[data-theme='light'] .journal-heading h2,
html[data-theme='light'] .journal-entry-title h3,
html[data-theme='light'] .journal-activity strong,
html[data-theme='light'] .badges-title h2,
html[data-theme='light'] .badge-card > strong { color:#102337; }
html[data-theme='light'] .challenge-program-action { color:#102337; background:linear-gradient(135deg,rgba(37,197,212,.16),#fff); }
html[data-theme='light'] .badge-card.unlocked { background:#e9fbf5; border-color:#67cdb0; }

/* Monthly Academic Progress Report */
.monthly-report-toolbar { display:flex; justify-content:space-between; gap:16px; align-items:center; margin-top:22px; padding:16px 18px; background:#0d1a29; border:1px solid rgba(37,197,212,.45); border-radius:18px; }
.monthly-report-toolbar strong,.monthly-report-toolbar span { display:block; }
.monthly-report-toolbar strong { color:#f4f9fc; font-size:15px; }
.monthly-report-toolbar span { margin-top:4px; color:#8094a5; font-size:11px; }
.monthly-report-toolbar button { min-height:44px; padding:10px 16px; color:#06111f; background:#25c5d4; border:0; border-radius:12px; cursor:pointer; font-size:12px; font-weight:900; white-space:nowrap; }
.monthly-report-page { display:grid; gap:18px; margin-top:22px; padding:22px; color:#152033; background:#f8fafc; border-left:4px solid #267af0; border-right:4px solid #267af0; border-radius:4px; }
.monthly-report-cover { display:grid; grid-template-columns:90px minmax(0,1fr); gap:20px; align-items:center; padding:12px 8px 28px; border-bottom:1px solid #d9e0e6; }
.report-logo { color:#22bce5; font-size:54px; font-weight:900; transform:rotate(-12deg); }
.monthly-report-cover h2 { max-width:470px; margin:0 0 14px auto; color:#111a2b; font-size:clamp(28px,7vw,48px); line-height:.97; text-align:right; }
.monthly-report-cover p { margin:0; color:#788797; font-size:12px; font-weight:800; letter-spacing:.12em; text-align:right; }
.monthly-report-card { padding:22px; background:#fff; border:1px solid #d7e0e7; border-radius:20px; box-shadow:0 4px 12px rgba(20,47,68,.06); }
.report-section-label { display:block; color:#8799a9; font-size:12px; font-weight:900; letter-spacing:.12em; }
.report-profile-card h3 { margin:13px 0 5px; color:#111a2b; font-size:28px; }
.report-profile-card > p { margin:0; color:#6f7e8c; font-size:14px; }
.report-profile-card > div { display:grid; grid-template-columns:repeat(2,1fr); gap:18px; margin-top:22px; }
.report-profile-card > div span,.report-profile-card small,.report-profile-card strong { display:block; }
.report-profile-card small { color:#97a5b2; font-size:10px; font-weight:800; letter-spacing:.1em; }
.report-profile-card strong { margin-top:7px; color:#1b2738; font-size:14px; }
.skill-radar-wrap { position:relative; max-width:430px; margin:8px auto 0; }
.skill-radar { display:block; width:100%; height:auto; overflow:visible; }
.radar-grid { fill:rgba(38,122,240,.025); stroke:#d4dde5; stroke-width:1; }
.radar-grid.outer { stroke:#bfcbd6; }
.radar-axis { stroke:#d9e1e8; stroke-width:1; }
.radar-value { fill:rgba(38,122,240,.18); stroke:#267af0; stroke-width:3; }
.skill-radar text { fill:#5f6f7e; font-size:8px; font-weight:800; }
.skill-radar-wrap > p { margin:5px 0 0; color:#81909d; font-size:12px; text-align:center; }
.report-score-grid { display:grid; grid-template-columns:1.15fr .85fr; gap:14px; }
.report-attendance-card > div { display:flex; justify-content:space-between; gap:12px; align-items:center; }
.report-attendance-card > div > strong { color:#10192a; font-size:38px; }
.report-attendance-card > p { display:grid; grid-template-columns:repeat(2,1fr); gap:10px; margin:16px 0 0; padding:14px; background:#f5f8fa; border-radius:14px; }
.report-attendance-card > p span { color:#768593; font-size:12px; }
.report-attendance-card > p b { float:right; color:#172335; }
.report-grade-card { display:grid; gap:10px; }
.report-grade-card > div { display:flex; justify-content:space-between; gap:12px; align-items:center; padding:12px; background:#f5f8fa; border-radius:13px; }
.report-grade-card span { color:#71808f; font-size:11px; font-weight:800; }
.report-grade-card strong { color:#267af0; font-size:28px; }
.report-comments,.report-table-section { padding:7px 0; }
.report-comments blockquote { margin:14px 0 0; padding:22px; color:#253243; background:#fff; border-left:5px solid #267af0; border-radius:16px; font-size:15px; line-height:1.7; }
.report-table-scroll { margin-top:14px; overflow-x:auto; background:#fff; border:1px solid #d7e0e7; border-radius:16px; }
.report-table-scroll table { width:100%; min-width:560px; border-collapse:collapse; }
.report-table-scroll th,.report-table-scroll td { padding:15px 13px; color:#263446; border-bottom:1px solid #e2e8ed; font-size:12px; text-align:left; }
.report-table-scroll th { color:#244b84; background:#eaf4fb; font-weight:900; }
.report-table-scroll tbody tr:last-child td { border-bottom:0; }
.report-empty { margin:14px 0 0; padding:18px; color:#758594; background:#fff; border:1px dashed #cbd6df; border-radius:14px; font-size:13px; text-align:center; }

html[data-theme='dark'] .monthly-report-page { color:#eaf1f6; background:#101a27; border-color:#25c5d4; }
html[data-theme='dark'] .monthly-report-cover { border-color:#2a3947; }
html[data-theme='dark'] .monthly-report-cover h2,
html[data-theme='dark'] .report-profile-card h3,
html[data-theme='dark'] .report-profile-card strong,
html[data-theme='dark'] .report-attendance-card > div > strong { color:#f2f7fa; }
html[data-theme='dark'] .monthly-report-card,
html[data-theme='dark'] .report-comments blockquote,
html[data-theme='dark'] .report-table-scroll,
html[data-theme='dark'] .report-empty { background:#0b1420; border-color:#2a3a48; }
html[data-theme='dark'] .report-attendance-card > p,
html[data-theme='dark'] .report-grade-card > div { background:#151f2b; }
html[data-theme='dark'] .report-attendance-card > p b,
html[data-theme='dark'] .report-comments blockquote,
html[data-theme='dark'] .report-table-scroll td { color:#dbe5ec; }
