.payment-proof-upload { display:grid; justify-items:center; gap:7px; padding:24px; border:2px dashed #34526a; border-radius:17px; text-align:center; cursor:pointer; }.payment-proof-upload input { position:absolute; width:1px; height:1px; opacity:0; }.payment-proof-upload>span { font-size:30px; color:#22d3ee; }.payment-proof-upload small { color:#91a7b7; }.submit-payment-proof { min-height:52px; border:0; border-radius:14px; color:#06202a; background:#22d3ee; font:inherit; font-weight:950; cursor:pointer; }.submit-payment-proof:disabled { opacity:.6; cursor:wait; }
