html[data-theme='light'] .payment-confirmation-form,html[data-theme='light'] .payment-confirmation-list>article { color:#14283a; background:#fff; border-color:#c8dce7; } html[data-theme='light'] .payment-method-grid>label,html[data-theme='light'] .payment-input-grid input,html[data-theme='light'] .payment-admin-note input,html[data-theme='light'] .payment-review-details>div { color:#14283a; background:#f4f8fa; border-color:#ccdce5; }
