  --moc-shadow-soft: 0 10px 28px rgba(0, 0, 0, 0.16);
  --moc-radius-xl: 28px;
  --moc-radius-lg: 22px;
  --moc-radius-md: 16px;
}

html[data-theme='light'] {
  --moc-bg: #f4f7fb;
  --moc-bg-soft: #eef4f9;
  --moc-surface: rgba(255, 255, 255, 0.91);
  --moc-surface-solid: #ffffff;
  --moc-surface-soft: #f7fafc;
  --moc-border: rgba(40, 76, 103, 0.12);
  --moc-border-strong: rgba(18, 146, 165, 0.26);
  --moc-text: #16283a;
  --moc-muted: #6f8294;
  --moc-subtle: #8b9baa;
  --moc-primary: #149eb3;
  --moc-primary-strong: #087f94;
  --moc-primary-soft: rgba(20, 158, 179, 0.10);
  --moc-shadow: 0 18px 48px rgba(31, 67, 92, 0.11);
  --moc-shadow-soft: 0 8px 24px rgba(31, 67, 92, 0.08);
}

body {
  color: var(--moc-text);
  background:
    radial-gradient(circle at 82% -10%, rgba(49, 128, 245, 0.18), transparent 31rem),
    radial-gradient(circle at 8% 22%, rgba(39, 205, 224, 0.10), transparent 24rem),
    var(--moc-bg);
}

html[data-theme='light'] body {
  background:
    radial-gradient(circle at 82% -8%, rgba(58, 130, 246, 0.10), transparent 30rem),
    linear-gradient(180deg, #f7fafe 0%, #f3f7fb 50%, #eef4f8 100%);
}

/* ---------- Main student shell ---------- */

.student-main-menu,
.student-full-menu,
.student-detail-page {
  width: min(100%, 940px) !important;
  max-width: 940px !important;
  min-height: 100vh;
  margin-inline: auto !important;
  color: var(--moc-text) !important;
  background: transparent !important;
}

.student-main-menu {
  padding: 12px 22px 54px !important;
}

.student-full-menu,
.student-detail-page {
  padding: 12px 22px 64px !important;
}

/* ---------- Header ---------- */

.student-dashboard-header,
.full-menu-header,
.student-detail-page > header {
  position: sticky !important;
  top: 10px !important;
  z-index: 65 !important;
  min-height: 68px !important;
  padding: 9px 11px !important;
  border: 1px solid var(--moc-border) !important;
  border-radius: 22px !important;
  background: color-mix(in srgb, var(--moc-surface-solid) 88%, transparent) !important;
  box-shadow: var(--moc-shadow-soft) !important;
  backdrop-filter: blur(22px) saturate(130%) !important;
  -webkit-backdrop-filter: blur(22px) saturate(130%) !important;
}

.student-dashboard-header {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  gap: 12px !important;
}

.student-dashboard-brand {
  min-width: 0;
  display: flex !important;
  align-items: center !important;
  gap: 10px !important;
}

.student-dashboard-brand .paper-plane-logo {
  flex: 0 0 42px !important;
  width: 42px !important;
  height: 42px !important;
  border-radius: 14px !important;
  color: #06141e !important;
  background: linear-gradient(145deg, #54e5f2, #28bdd6) !important;
  box-shadow: 0 8px 22px rgba(39, 205, 224, 0.22) !important;
}

.student-dashboard-brand .paper-plane-logo svg {
  width: 28px !important;
  height: 28px !important;
}

.student-dashboard-brand strong {
  display: block;
  overflow: hidden;
  color: var(--moc-text) !important;
  font-size: 14px !important;
  font-weight: 800 !important;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.student-dashboard-brand span {
  display: block;
  margin-top: 2px;
  color: var(--moc-muted) !important;
  font-size: 10px !important;
  font-weight: 600 !important;
}

.student-header-actions {
  display: flex !important;
  align-items: center !important;
  gap: 7px !important;
}

.student-profile-trigger,
.student-header-refresh {
  display: grid !important;
  place-items: center !important;
  flex: 0 0 40px !important;
  width: 40px !important;
  height: 40px !important;
  padding: 0 !important;
  border: 1px solid var(--moc-border) !important;
  border-radius: 13px !important;
  color: var(--moc-primary) !important;
  background: var(--moc-surface-soft) !important;
  box-shadow: none !important;
  cursor: pointer !important;
}

.student-profile-trigger {
  overflow: hidden;
  border-radius: 50% !important;
  color: #06202a !important;
  background: linear-gradient(145deg, #67e8f9, #24b6cf) !important;
  font-size: 12px !important;
  font-weight: 900 !important;
}

.student-profile-trigger img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.student-profile-trigger > span {
  display: grid !important;
  place-items: center !important;
  width: 100%;
  height: 100%;
  margin: 0 !important;
  color: #06202a !important;
  font-size: 11px !important;
}

.student-header-refresh {
  font-size: 22px !important;
}

.theme-switch {
  min-height: 40px !important;
  padding: 4px !important;
  border: 1px solid var(--moc-border) !important;
  border-radius: 13px !important;
  background: var(--moc-surface-soft) !important;
}

.theme-switch button {
  min-width: 42px !important;
  min-height: 30px !important;
  padding: 5px 8px !important;
  border-radius: 9px !important;
  color: var(--moc-muted) !important;
  font-size: 8px !important;
  font-weight: 800 !important;
  letter-spacing: .04em !important;
}

.theme-switch button.active {
  color: #06202a !important;
  background: var(--moc-primary) !important;
  box-shadow: none !important;
}

/* ---------- Account popover ---------- */

.student-drawer {
  position: fixed !important;
  top: 88px !important;
  right: max(14px, calc(50% - 454px)) !important;
  left: auto !important;
  z-index: 90 !important;
  width: min(272px, calc(100vw - 28px)) !important;
  padding: 8px !important;
  border: 1px solid var(--moc-border) !important;
  border-radius: 18px !important;
  background: var(--moc-surface-solid) !important;
  box-shadow: 0 24px 70px rgba(0, 0, 0, .34) !important;
}

.student-drawer button {
  min-height: 48px !important;
  padding: 12px 13px !important;
  border: 0 !important;
  border-radius: 12px !important;
  color: var(--moc-text) !important;
  background: transparent !important;
}

.student-drawer button:hover {
  background: var(--moc-primary-soft) !important;
}

.student-drawer-backdrop {
  z-index: 80 !important;
  background: rgba(3, 10, 18, .42) !important;
  backdrop-filter: blur(3px);
}

/* ---------- Floating left navigation ---------- */

.student-bottom-navigation {
  position: fixed !important;
  top: 50% !important;
  right: auto !important;
  bottom: auto !important;
  left: max(10px, calc(50% - 525px)) !important;
  z-index: 75 !important;
  width: 64px !important;
  padding: 8px !important;
  display: flex !important;
  grid-template-columns: none !important;
  flex-direction: column !important;
  gap: 7px !important;
  transform: translateY(-50%) !important;
  border: 1px solid var(--moc-border) !important;
  border-radius: 22px !important;
  background: color-mix(in srgb, var(--moc-surface-solid) 90%, transparent) !important;
  box-shadow: 0 18px 48px rgba(0, 0, 0, .26) !important;
  backdrop-filter: blur(22px) saturate(140%) !important;
  -webkit-backdrop-filter: blur(22px) saturate(140%) !important;
}

.student-bottom-navigation button {
  position: relative !important;
  width: 48px !important;
  min-width: 48px !important;
  height: 48px !important;
  min-height: 48px !important;
  margin: 0 !important;
  padding: 0 !important;
  display: grid !important;
  place-items: center !important;
  border: 0 !important;
  border-radius: 15px !important;
  color: var(--moc-muted) !important;
  background: transparent !important;
  cursor: pointer !important;
  font-size: 0 !important;
  transition: transform .18s ease, background .18s ease, color .18s ease !important;
}

.student-bottom-navigation button:hover {
  color: var(--moc-primary) !important;
  background: var(--moc-primary-soft) !important;
  transform: translateY(-1px);
}

.student-bottom-navigation button.active {
  color: var(--moc-primary) !important;
  background: linear-gradient(145deg, rgba(39, 205, 224, .18), rgba(63, 125, 244, .10)) !important;
  box-shadow: inset 0 0 0 1px rgba(39, 205, 224, .12) !important;
}

.student-bottom-navigation button.active::before {
  content: "";
  position: absolute;
  left: -8px;
  width: 3px;
  height: 22px;
  border-radius: 999px;
  background: var(--moc-primary);
  box-shadow: 0 0 12px rgba(39, 205, 224, .58);
}

.student-nav-icon {
  width: 22px !important;
  height: 22px !important;
  display: block !important;
}

.student-nav-label {
  position: absolute !important;
  left: 59px !important;
  top: 50% !important;
  z-index: 4;
  min-width: max-content;
  padding: 7px 10px !important;
  border: 1px solid var(--moc-border) !important;
  border-radius: 9px !important;
  color: var(--moc-text) !important;
  background: var(--moc-surface-solid) !important;
  box-shadow: var(--moc-shadow-soft) !important;
  opacity: 0;
  pointer-events: none;
  transform: translate(-5px, -50%);
  transition: opacity .15s ease, transform .15s ease;
  font-size: 11px !important;
  font-weight: 750 !important;
  white-space: nowrap;
}

.student-bottom-navigation button:hover .student-nav-label,
.student-bottom-navigation button:focus-visible .student-nav-label {
  opacity: 1;
  transform: translate(0, -50%);
}

/* ---------- Student hero ---------- */

.student-hero-card {
  position: relative !important;
  overflow: hidden !important;
  margin-top: 18px !important;
  padding: clamp(22px, 4.6vw, 38px) !important;
  border: 1px solid var(--moc-border) !important;
  border-radius: var(--moc-radius-xl) !important;
  background:
    radial-gradient(circle at 93% 4%, rgba(39, 205, 224, .16), transparent 20rem),
    linear-gradient(145deg, rgba(17, 36, 55, .96), rgba(9, 23, 37, .96)) !important;
  box-shadow: var(--moc-shadow) !important;
}

html[data-theme='light'] .student-hero-card {
  background:
    radial-gradient(circle at 93% 4%, rgba(39, 205, 224, .14), transparent 19rem),
    linear-gradient(145deg, #ffffff, #f7fbfd) !important;
}

.student-sun-icon {
  width: 56px !important;
  height: 56px !important;
  margin: 0 0 18px !important;
  border: 1px solid var(--moc-border) !important;
  border-radius: 17px !important;
  background: var(--moc-surface-soft) !important;
  box-shadow: none !important;
  font-size: 29px !important;
}

.student-greeting {
  margin: 0 !important;
  color: var(--moc-text) !important;
  font-size: clamp(28px, 5vw, 44px) !important;
  line-height: 1.06 !important;
  letter-spacing: -.035em;
}

.student-greeting span {
  margin-top: 4px !important;
  color: var(--moc-primary) !important;
  font-size: .92em !important;
}

.student-motivation {
  max-width: 590px !important;
  margin: 13px 0 22px !important;
  color: var(--moc-muted) !important;
  font-size: clamp(13px, 2vw, 16px) !important;
  line-height: 1.65 !important;
}

.student-date-row,
.student-time-row {
  min-height: 52px !important;
  margin-top: 10px !important;
  padding: 10px 14px !important;
  border: 1px solid var(--moc-border) !important;
  border-radius: 15px !important;
  color: var(--moc-text) !important;
  background: color-mix(in srgb, var(--moc-surface-soft) 88%, transparent) !important;
  font-size: 13px !important;
  font-weight: 650 !important;
}

.student-date-row span,
.student-time-row span {
  flex: 0 0 26px;
  color: var(--moc-primary) !important;
  font-size: 20px !important;
}

.student-time-row {
  color: var(--moc-primary) !important;
  background: var(--moc-primary-soft) !important;
  border-color: var(--moc-border-strong) !important;
}

/* ---------- Weather ---------- */

.student-weather-card {
  margin-top: 18px !important;
  padding: 18px !important;
  border: 1px solid var(--moc-border) !important;
  border-radius: 21px !important;
  background: color-mix(in srgb, var(--moc-surface-soft) 86%, transparent) !important;
  box-shadow: none !important;
}

.weather-main {
  grid-template-columns: 56px minmax(0, 1fr) auto !important;
  gap: 13px !important;
  padding-bottom: 15px !important;
  border-bottom-color: var(--moc-border) !important;
}

.weather-icon {
  width: 56px !important;
  height: 56px !important;
  border: 1px solid var(--moc-border) !important;
  border-radius: 16px !important;
  background: var(--moc-surface-solid) !important;
  font-size: 29px !important;
}

.weather-main strong {
  color: var(--moc-text) !important;
  font-size: clamp(28px, 6vw, 38px) !important;
  line-height: 1 !important;
}

.weather-main div > span {
  margin-top: 6px !important;
  color: var(--moc-primary) !important;
  font-size: 10px !important;
  letter-spacing: .06em !important;
}

.weather-main p {
  color: var(--moc-muted) !important;
  font-size: 12px !important;
}

.weather-details {
  gap: 8px !important;
  margin-top: 13px !important;
}

.weather-details div {
  padding: 11px 6px !important;
  border: 1px solid var(--moc-border) !important;
  border-radius: 13px !important;
  background: var(--moc-surface-solid) !important;
}

.weather-details span {
  color: var(--moc-subtle) !important;
  font-size: 8px !important;
}

.weather-details strong {
  margin-top: 6px !important;
  color: var(--moc-text) !important;
  font-size: 13px !important;
}

/* ---------- Rank / EXP ---------- */

.student-status-area {
  margin-top: 16px !important;
}

.student-rank-card {
  position: relative !important;
  overflow: hidden !important;
  padding: 22px !important;
  border: 1px solid var(--moc-border) !important;
  border-radius: 22px !important;
  background: linear-gradient(145deg, rgba(13, 30, 46, .92), rgba(8, 20, 33, .92)) !important;
  box-shadow: none !important;
  text-align: left !important;
}

html[data-theme='light'] .student-rank-card {
  background: #ffffff !important;
}

.rank-brand {
  display: block !important;
  margin-bottom: 15px !important;
  color: var(--moc-subtle) !important;
  font-size: 9px !important;
  font-weight: 850 !important;
  letter-spacing: .16em !important;
}

.rank-emblem {
  width: auto !important;
  margin: 0 0 13px !important;
  display: inline-flex !important;
  align-items: center !important;
  gap: 8px !important;
  border: 0 !important;
  background: transparent !important;
}

.rank-emblem > span {
  display: grid !important;
  place-items: center !important;
  width: 42px !important;
  height: 42px !important;
  border: 1px solid rgba(39, 205, 224, .28) !important;
  border-radius: 14px !important;
  color: #06202a !important;
  background: var(--moc-primary) !important;
  font-size: 20px !important;
  box-shadow: 0 8px 20px rgba(39, 205, 224, .18) !important;
}

.rank-emblem small {
  position: static !important;
  width: auto !important;
  margin: 0 !important;
  padding: 7px 10px !important;
  border: 1px solid var(--moc-border) !important;
  border-radius: 999px !important;
  color: var(--moc-muted) !important;
  background: var(--moc-surface-soft) !important;
  font-size: 8px !important;
  letter-spacing: .12em !important;
}

.student-rank-card > p {
  margin: 0 !important;
  color: var(--moc-muted) !important;
  font-size: 9px !important;
  font-weight: 750 !important;
  letter-spacing: .08em !important;
}

.student-rank-card h2 {
  margin: 6px 0 15px !important;
  color: var(--moc-text) !important;
  font-size: clamp(25px, 5vw, 34px) !important;
  letter-spacing: -.03em !important;
}

.exp-progress {
  height: 9px !important;
  overflow: hidden !important;
  border: 1px solid var(--moc-border) !important;
  border-radius: 999px !important;
  background: var(--moc-surface-soft) !important;
}

.exp-progress > span {
  display: block !important;
  height: 100% !important;
  border-radius: inherit !important;
  background: linear-gradient(90deg, var(--moc-primary), #5f8cff) !important;
  box-shadow: 0 0 13px rgba(39, 205, 224, .36) !important;
}

.exp-meta {
  margin-top: 12px !important;
}

.exp-meta strong {
  color: var(--moc-text) !important;
  font-size: 12px !important;
}

.exp-meta span {
  color: var(--moc-muted) !important;
  font-size: 10px !important;
  line-height: 1.45 !important;
}

/* ---------- Badges ---------- */

.home-badges-section,
.badges-section {
  margin-top: 18px !important;
}

.badges-title {
  align-items: center !important;
  margin-bottom: 12px !important;
}

.badges-title > span {
  display: grid !important;
  place-items: center !important;
  flex: 0 0 42px !important;
  width: 42px !important;
  height: 42px !important;
  border: 1px solid var(--moc-border) !important;
  border-radius: 14px !important;
  background: var(--moc-surface-solid) !important;
  font-size: 20px !important;
}

.badges-title h2 {
  margin: 0 !important;
  color: var(--moc-text) !important;
  font-size: 17px !important;
}

.badges-title p {
  margin: 3px 0 0 !important;
  color: var(--moc-muted) !important;
  font-size: 10px !important;
}

.badges-grid {
  display: grid !important;
  grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
  gap: 10px !important;
}

.badge-card {
  min-width: 0 !important;
  min-height: 136px !important;
  padding: 15px !important;
  border: 1px solid var(--moc-border) !important;
  border-radius: 18px !important;
  background: var(--moc-surface-solid) !important;
  box-shadow: none !important;
}

.badge-card.unlocked {
  border-color: rgba(59, 213, 159, .28) !important;
  background: linear-gradient(145deg, rgba(59, 213, 159, .08), var(--moc-surface-solid)) !important;
}

.badge-icon {
  display: grid !important;
  place-items: center !important;
  width: 38px !important;
  height: 38px !important;
  margin: 0 0 12px !important;
  border-radius: 12px !important;
  color: var(--moc-primary) !important;
  background: var(--moc-primary-soft) !important;
  font-size: 19px !important;
}

.badge-card strong {
  color: var(--moc-text) !important;
  font-size: 12px !important;
}

.badge-card small {
  margin-top: 4px !important;
  color: var(--moc-muted) !important;
  font-size: 9px !important;
  line-height: 1.4 !important;
}

.badge-card b {
  margin-top: 10px !important;
  color: var(--moc-primary) !important;
  font-size: 8px !important;
  letter-spacing: .09em !important;
}

.badge-card.locked {
  opacity: .56 !important;
  filter: saturate(.65) !important;
}

/* ---------- Full menu ---------- */

.full-menu-header {
  display: grid !important;
  grid-template-columns: 42px 1fr auto 42px !important;
  align-items: center !important;
  gap: 10px !important;
}

.full-menu-header > button {
  width: 40px !important;
  height: 40px !important;
  border: 1px solid var(--moc-border) !important;
  border-radius: 13px !important;
  color: var(--moc-primary) !important;
  background: var(--moc-surface-soft) !important;
}

.full-menu-header h1 {
  margin: 0 !important;
  color: var(--moc-text) !important;
  font-size: 15px !important;
  letter-spacing: .02em !important;
}

.full-cloud-status {
  padding: 7px 10px !important;
  border: 1px solid rgba(59, 213, 159, .22) !important;
  border-radius: 999px !important;
  color: var(--moc-green) !important;
  background: rgba(59, 213, 159, .07) !important;
  font-size: 9px !important;
}

.scroll-report-cards {
  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  gap: 12px !important;
  margin-top: 18px !important;
}

.scroll-report-cards > button {
  min-height: 130px !important;
  padding: 18px !important;
  border: 1px solid var(--moc-border) !important;
  border-top: 1px solid var(--moc-border) !important;
  border-radius: 20px !important;
  color: var(--moc-text) !important;
  background: var(--moc-surface-solid) !important;
  box-shadow: var(--moc-shadow-soft) !important;
}

.scroll-report-cards > button:hover {
  border-color: var(--moc-border-strong) !important;
  transform: translateY(-1px);
}

.scroll-report-cards span {
  color: var(--moc-muted) !important;
  font-size: 11px !important;
}

.scroll-report-cards .report-text-value {
  margin: 8px 0 !important;
  color: var(--moc-text) !important;
  font-size: 17px !important;
}

.scroll-report-cards small {
  color: var(--moc-subtle) !important;
  font-size: 10px !important;
}

.scroll-report-cards i {
  flex: 0 0 46px !important;
  width: 46px !important;
  height: 46px !important;
  border-radius: 14px !important;
  font-size: 22px !important;
}

.full-menu-logout {
  margin-top: 18px !important;
  min-height: 48px !important;
  border-radius: 14px !important;
}

/* ---------- Detail pages ---------- */

.student-detail-page > header {
  display: flex !important;
  align-items: center !important;
  gap: 11px !important;
  border-bottom: 1px solid var(--moc-border) !important;
}

.student-detail-page > header button {
  width: 40px !important;
  height: 40px !important;
  border: 1px solid var(--moc-border) !important;
  border-radius: 13px !important;
  color: var(--moc-primary) !important;
  background: var(--moc-surface-soft) !important;
}

.student-detail-page > header h1 {
  color: var(--moc-text) !important;
  font-size: 17px !important;
}

.detail-panel {
  margin-top: 16px !important;
  padding: clamp(18px, 3vw, 24px) !important;
  border: 1px solid var(--moc-border) !important;
  border-radius: 22px !important;
  color: var(--moc-text) !important;
