/* ========================================================================== 
   MOC ACADEMIC SUITE — FINAL UI STABILITY LAYER V2
   07 Sep 2026
   - Inline SVG logo-safe login
   - Clean modern sign-in screen
   - Stable Dark / Light themes
   - Floating student navigation remains on the left
   This block intentionally sits LAST so old iterative rules cannot override it.
   ========================================================================== */

:root,
html[data-theme='dark'] {
  color-scheme: dark;
  --ui-bg: #07111f;
  --ui-bg-2: #0a1726;
  --ui-surface: #0c1928;
  --ui-surface-2: #101f31;
  --ui-field: #081421;
  --ui-text: #f6f9fc;
  --ui-text-2: #a5b5c4;
  --ui-muted: #73889c;
  --ui-line: rgba(149, 184, 207, .16);
  --ui-line-strong: rgba(39, 205, 224, .31);
  --ui-accent: #27cde0;
  --ui-accent-strong: #12afca;
  --ui-accent-soft: rgba(39, 205, 224, .11);
  --ui-green: #3bd59f;
  --ui-danger: #fb7185;
  --ui-shadow: 0 24px 70px rgba(0,0,0,.28);
  --ui-shadow-soft: 0 10px 30px rgba(0,0,0,.18);
}

html[data-theme='light'] {
  color-scheme: light;
  --ui-bg: #f2f6fa;
  --ui-bg-2: #eaf1f6;
  --ui-surface: #ffffff;
  --ui-surface-2: #f7fafc;
  --ui-field: #f8fbfd;
  --ui-text: #13293b;
  --ui-text-2: #526b7d;
  --ui-muted: #7c8f9f;
  --ui-line: rgba(44, 78, 103, .13);
  --ui-line-strong: rgba(20, 158, 179, .27);
  --ui-accent: #149eb3;
  --ui-accent-strong: #087f94;
  --ui-accent-soft: rgba(20, 158, 179, .10);
  --ui-green: #15996d;
  --ui-danger: #d94b60;
  --ui-shadow: 0 24px 60px rgba(39, 75, 101, .12);
  --ui-shadow-soft: 0 8px 28px rgba(39, 75, 101, .08);
}

html,
body,
#root {
  min-height: 100%;
  background: var(--ui-bg) !important;
}

body {
  color: var(--ui-text) !important;
  transition: background-color .18s ease, color .18s ease;
}

html[data-theme='dark'] body {
  background:
    radial-gradient(circle at 84% -8%, rgba(56, 126, 245, .16), transparent 31rem),
    radial-gradient(circle at 7% 26%, rgba(39, 205, 224, .08), transparent 24rem),
    var(--ui-bg) !important;
}

html[data-theme='light'] body {
  background:
    radial-gradient(circle at 84% -8%, rgba(56, 126, 245, .08), transparent 31rem),
    linear-gradient(180deg, #f8fbfd 0%, #f1f6f9 56%, #edf3f7 100%) !important;
}

