/* ========================================================================== */
/* MOC UI V3 — FLOATING NAV THAT DOES NOT STEAL PAGE WIDTH                     */
/* Final override. Keep this block at the very end of index.css.               */
/* ========================================================================== */

/* The student page keeps its full usable width. The rail floats over it only
   while open, so the content is never permanently squeezed to the right. */
.student-main-menu,
.student-full-menu,
.student-detail-page {
  width: 100% !important;
  max-width: 760px !important;
  margin-inline: auto !important;
  padding-left: 14px !important;
  padding-right: 14px !important;
}

.student-main-menu {
  overflow-x: clip !important;
}

/* Outer shell controls open/close animation. */
.student-floating-nav-shell {
  position: fixed !important;
  top: 50% !important;
  left: 0 !important;
  z-index: 90 !important;
  display: flex !important;
  align-items: center !important;
  transform: translateY(-50%) !important;
  transition: transform .24s ease !important;
  pointer-events: none !important;
}

.student-floating-nav-shell.expanded {
  transform: translateY(-50%) translateX(0) !important;
}

/* Hide the rail completely except for a small reopen handle. */
.student-floating-nav-shell.collapsed {
  transform: translateY(-50%) translateX(-62px) !important;
}

.student-floating-nav-shell .student-bottom-navigation {
  position: relative !important;
  inset: auto !important;
  top: auto !important;
  right: auto !important;
  bottom: auto !important;
  left: auto !important;
  width: 62px !important;
  margin: 0 !important;
  padding: 7px 6px !important;
  display: flex !important;
  flex-direction: column !important;
  gap: 6px !important;
  transform: none !important;
  pointer-events: auto !important;
  border: 1px solid var(--ui-line) !important;
  border-left: 0 !important;
  border-radius: 0 20px 20px 0 !important;
  background: color-mix(in srgb, var(--ui-surface) 92%, transparent) !important;
  box-shadow: 0 18px 42px rgba(0, 0, 0, .30) !important;
  backdrop-filter: blur(20px) saturate(135%) !important;
  -webkit-backdrop-filter: blur(20px) saturate(135%) !important;
}

.student-bottom-navigation button {
  position: relative !important;
  width: 48px !important;
  min-width: 48px !important;
  height: 48px !important;
  min-height: 48px !important;
  padding: 0 !important;
  display: grid !important;
  place-items: center !important;
  color: var(--ui-muted) !important;
  background: transparent !important;
  border: 0 !important;
  border-radius: 14px !important;
}

.student-bottom-navigation button.active {
  color: var(--ui-accent) !important;
  background: var(--ui-accent-soft) !important;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ui-accent) 26%, transparent) !important;
}

.student-bottom-navigation button.active::before {
  content: '' !important;
  position: absolute !important;
  left: -7px !important;
  width: 3px !important;
  height: 22px !important;
  border-radius: 99px !important;
  background: var(--ui-accent) !important;
  box-shadow: 0 0 12px color-mix(in srgb, var(--ui-accent) 65%, transparent) !important;
}

.student-nav-icon {
  width: 22px !important;
  height: 22px !important;
}

/* Labels act as tooltips and do not increase rail width. */
.student-nav-label {
  position: absolute !important;
  left: 58px !important;
  top: 50% !important;
  z-index: 3 !important;
  width: max-content !important;
  margin: 0 !important;
  padding: 7px 10px !important;
  transform: translate(4px, -50%) !important;
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
  color: var(--ui-text) !important;
  background: var(--ui-surface) !important;
  border: 1px solid var(--ui-line) !important;
  border-radius: 10px !important;
  box-shadow: var(--ui-shadow-soft) !important;
  font-size: 10px !important;
  font-weight: 800 !important;
  white-space: nowrap !important;
  transition: opacity .15s ease, transform .15s ease, visibility .15s ease !important;
}

.student-bottom-navigation button:hover .student-nav-label,
.student-bottom-navigation button:focus-visible .student-nav-label {
  opacity: 1 !important;
  visibility: visible !important;
  transform: translate(0, -50%) !important;
}

/* Small tab always remains visible so the user can reopen the rail. */
.student-floating-nav-toggle {
  position: relative !important;
  z-index: 4 !important;
  flex: 0 0 27px !important;
  width: 27px !important;
  height: 54px !important;
  margin-left: -1px !important;
  padding: 0 !important;
  display: grid !important;
  place-items: center !important;
  pointer-events: auto !important;
  color: var(--ui-accent) !important;
  background: color-mix(in srgb, var(--ui-surface) 94%, transparent) !important;
  border: 1px solid var(--ui-line) !important;
  border-left: 0 !important;
  border-radius: 0 14px 14px 0 !important;
  box-shadow: 8px 10px 26px rgba(0, 0, 0, .18) !important;
  backdrop-filter: blur(18px) !important;
  -webkit-backdrop-filter: blur(18px) !important;
  cursor: pointer !important;
}

.student-floating-nav-toggle svg {
  width: 17px !important;
  height: 17px !important;
  fill: none !important;
  stroke: currentColor !important;
  stroke-width: 2 !important;
  stroke-linecap: round !important;
  stroke-linejoin: round !important;
}

/* Home cards stay centered and full-width; no left gutter is reserved. */
.student-dashboard-header,
.student-hero-card,
.badges-section,
.academic-overview,
.student-system-status,
.student-quick-menu {
  width: 100% !important;
