/* =========================================================
   V22 — Gamification Engine UI
   ========================================================= */

.gamification-reward-toast {
  position: fixed;
  top: 86px;
  right: 22px;
  z-index: 10050;
  width: min(360px, calc(100vw - 32px));
  display: grid;
  grid-template-columns: 48px 1fr 28px;
  gap: 12px;
  align-items: center;
  padding: 14px;
  background: rgba(9, 25, 39, .96);
  border: 1px solid rgba(37, 197, 212, .42);
  border-radius: 18px;
  box-shadow: 0 20px 60px rgba(0,0,0,.32);
  backdrop-filter: blur(12px);
  animation: mocRewardIn .28s ease-out;
}

.gamification-reward-toast.badge-unlock {
  border-color: rgba(243,198,92,.48);
}

.gamification-reward-toast.rank-up {
  border-color: rgba(130,82,230,.55);
}

.gamification-reward-icon {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  color: #06121c;
  background: linear-gradient(145deg, #25c5d4, #39e2a0);
  border-radius: 15px;
}

.gamification-reward-toast.badge-unlock .gamification-reward-icon {
  background: linear-gradient(145deg, #f3c65c, #ff9c5a);
}

.gamification-reward-toast.rank-up .gamification-reward-icon {
  color: #fff;
  background: linear-gradient(145deg, #8252e6, #25c5d4);
}

.gamification-reward-icon .badge-glyph {
  width: 27px;
  height: 27px;
}

.gamification-reward-toast small,
.gamification-reward-toast strong,
.gamification-reward-toast span {
  display: block;
}

.gamification-reward-toast small {
  color: #76dfe9;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .12em;
}

.gamification-reward-toast strong {
  margin-top: 4px;
  color: #f3f8fb;
  font-size: 13px;
}

.gamification-reward-toast span {
  margin-top: 4px;
  color: #39e2a0;
  font-size: 12px;
  font-weight: 900;
}

.gamification-reward-toast > button {
  width: 28px;
  height: 28px;
  color: #8597a7;
  background: transparent;
  border: 0;
  cursor: pointer;
  font-size: 22px;
}

@keyframes mocRewardIn {
  from { opacity: 0; transform: translateY(-8px) scale(.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.profile-gamification-card {
  margin: 8px 0 18px;
  padding: 16px;
  background: linear-gradient(145deg, rgba(37,197,212,.08), rgba(130,82,230,.06));
  border: 1px solid #244057;
  border-radius: 18px;
}

.profile-gamification-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 8px;
}

.profile-gamification-summary > div {
  min-width: 0;
  padding: 12px;
  background: #0a1724;
  border: 1px solid #22384a;
  border-radius: 13px;
}

.profile-gamification-summary small,
.profile-gamification-summary strong {
  display: block;
}

.profile-gamification-summary small {
  color: #738a9d;
  font-size: 8px;
  font-weight: 900;
}

.profile-gamification-summary strong {
  margin-top: 6px;
  color: #f1f7fa;
  font-size: 15px;
}

.profile-gamification-note {
  margin: 12px 2px 0;
  color: #8599a9;
  font-size: 10px;
  line-height: 1.55;
}

.profile-exp-breakdown {
  display: grid;
  gap: 8px;
  margin-top: 14px;
}

.profile-exp-breakdown > div {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 6px 10px;
  align-items: center;
}

.profile-exp-breakdown span,
.profile-exp-breakdown strong {
  font-size: 10px;
}

.profile-exp-breakdown span {
  color: #b5c3ce;
  font-weight: 700;
}

.profile-exp-breakdown strong {
  color: #39e2a0;
}

.profile-exp-breakdown i {
  grid-column: 1 / -1;
  height: 6px;
  overflow: hidden;
  background: #09131e;
  border-radius: 999px;
}

.profile-exp-breakdown i b {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, #25c5d4, #39e2a0);
  border-radius: inherit;
}

.profile-leaderboard {
  margin-top: 16px;
  padding-top: 14px;
  border-top: 1px solid #22384a;
}

.profile-leaderboard header {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 8px;
}

.profile-leaderboard header span {
  color: #7f92a2;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .08em;
}

.profile-leaderboard header small {
  color: #25c5d4;
  font-size: 9px;
}

.profile-leaderboard > div {
  display: grid;
  grid-template-columns: 32px 1fr auto;
  gap: 8px;
  align-items: center;
  padding: 9px 10px;
  border-radius: 10px;
}

.profile-leaderboard > div.me {
  background: rgba(37,197,212,.1);
}

.profile-leaderboard > div b {
  color: #f3c65c;
  font-size: 10px;
}

.profile-leaderboard > div span {
  color: #c8d5de;
  font-size: 10px;
}

.profile-leaderboard > div strong {
  color: #39e2a0;
  font-size: 10px;
}

html[data-theme='light'] .profile-gamification-card {
  background: #f8fcfd;
  border-color: #c9e3e8;
}

html[data-theme='light'] .profile-gamification-summary > div {
  background: #fff;
  border-color: #dce8ed;
}

html[data-theme='light'] .profile-gamification-summary strong,
html[data-theme='light'] .profile-leaderboard > div span {
  color: #102337;
}

@media (max-width: 560px) {
  .gamification-reward-toast {
    top: 76px;
    right: 16px;
  }

  .profile-gamification-summary {
    grid-template-columns: 1fr;
  }
}


/* =========================================================
   V23 — Formal Grammar Program Report
   Only monthly report presentation for Grammar students.
   ========================================================= */

.grammar-stage-card {
  background: #ffffff !important;
}

.grammar-stage-track {
