/* =========================================================
   V25 — REGISTRATION CHECKOUT
   Tambahan khusus alur daftar → jadwal → pembayaran awal.
   ========================================================= */
.registration-checkout-modal { max-width: 760px; }
.registration-stepper { display:flex; align-items:center; gap:12px; padding:0 28px 18px; }
.registration-stepper > span { display:flex; align-items:center; gap:8px; color:var(--muted-text, #8993a3); font-size:.78rem; font-weight:700; }
.registration-stepper > span b { display:grid; place-items:center; width:28px; height:28px; border-radius:50%; background:rgba(127,127,127,.14); }
.registration-stepper > span.active { color:#1aa5a5; }
.registration-stepper > span.active b, .registration-stepper > span.done b { background:#1aa5a5; color:#fff; }
.registration-stepper > i { flex:1; height:1px; background:rgba(127,127,127,.22); }
.registration-program-grid select:disabled { opacity:.65; cursor:not-allowed; }
.registration-schedule-note { color:#d48b22; margin-top:6px; }
.registration-order-summary { display:grid; grid-template-columns:1fr 2fr auto; gap:12px; align-items:center; padding:14px 16px; border-radius:16px; background:rgba(22,155,155,.08); border:1px solid rgba(22,155,155,.18); margin-bottom:18px; }
.registration-order-summary div { display:flex; flex-direction:column; gap:3px; }
.registration-order-summary span { font-size:.68rem; color:var(--muted-text, #8d97a5); text-transform:uppercase; letter-spacing:.08em; }
.registration-order-summary strong { font-size:.88rem; }
.registration-order-summary button { border:0; background:none; color:#169b9b; font-weight:800; cursor:pointer; }
.registration-checkout-section { border:1px solid rgba(127,127,127,.18); border-radius:18px; padding:16px; margin-bottom:16px; background:rgba(127,127,127,.035); }
.registration-checkout-heading { display:flex; gap:10px; align-items:center; margin-bottom:14px; }
.registration-checkout-heading > span { width:34px; height:34px; display:grid; place-items:center; border-radius:11px; background:#169b9b; color:#fff; font-size:.75rem; font-weight:800; }
.registration-checkout-heading > div { display:flex; flex-direction:column; }
.registration-checkout-heading strong { font-size:.92rem; }
.registration-checkout-heading small { color:var(--muted-text, #8d97a5); }
.registration-product-line { display:grid !important; grid-template-columns:auto 1fr auto; align-items:center; gap:12px; padding:13px 0; border-bottom:1px solid rgba(127,127,127,.12); cursor:pointer; }
.registration-product-line:last-of-type { border-bottom:0; }
.registration-product-line input { width:18px !important; height:18px; accent-color:#169b9b; }
.registration-product-line > div { display:flex; flex-direction:column; }
.registration-product-line > div strong { font-size:.85rem; }
.registration-product-line > div small { color:var(--muted-text, #8d97a5); }
.registration-product-line > b { font-size:.85rem; white-space:nowrap; }
.registration-product-line.mandatory { cursor:default; }
.registration-file-upload { display:flex !important; flex-direction:column; align-items:center; justify-content:center; text-align:center; gap:5px; margin-top:14px; padding:18px; border:1.5px dashed rgba(22,155,155,.42); border-radius:15px; background:rgba(22,155,155,.05); cursor:pointer; }
.registration-file-upload input { display:none; }
.registration-file-upload > span { font-size:1.5rem; }
.registration-file-upload > strong { font-size:.82rem; }
.registration-file-upload > small { color:var(--muted-text, #8d97a5); max-width:460px; }
.registration-bank-list { display:grid; grid-template-columns:1fr 1fr; gap:10px; }
.registration-bank-list > button { display:flex; justify-content:space-between; align-items:center; gap:12px; width:100%; padding:13px; text-align:left; border-radius:14px; border:1px solid rgba(127,127,127,.18); background:transparent; color:inherit; cursor:pointer; }
.registration-bank-list > button.selected { border-color:#169b9b; box-shadow:0 0 0 2px rgba(22,155,155,.08); background:rgba(22,155,155,.05); }
.registration-bank-list > button div { display:flex; flex-direction:column; gap:2px; }
.registration-bank-list > button div span { font-size:.67rem; color:#169b9b; font-weight:800; }
.registration-bank-list > button div strong { font-size:1rem; letter-spacing:.03em; }
.registration-bank-list > button div small { color:var(--muted-text, #8d97a5); }
.registration-bank-list em { font-style:normal; color:#169b9b; font-size:.72rem; font-weight:800; padding:6px 8px; border-radius:8px; background:rgba(22,155,155,.08); }
.registration-copy-message { margin-top:8px; font-size:.72rem; color:#169b9b; text-align:center; }
.registration-total { display:flex; justify-content:space-between; align-items:center; margin-top:14px; padding:14px; border-radius:14px; background:rgba(248,195,62,.1); }
.registration-total span { font-size:.78rem; font-weight:700; }
.registration-total strong { font-size:1.15rem; color:#d49a00; }
.registration-checkout-note, .registration-success-next { padding:14px; border-radius:14px; background:rgba(22,155,155,.07); border:1px solid rgba(22,155,155,.16); margin-bottom:14px; }
.registration-checkout-note strong, .registration-success-next strong { font-size:.8rem; color:#169b9b; }
.registration-checkout-note p, .registration-success-next p { margin:5px 0 0; color:var(--muted-text, #8d97a5); font-size:.76rem; line-height:1.6; }
.registration-success-content { padding:28px; text-align:center; }
.registration-success-icon { width:62px; height:62px; display:grid; place-items:center; margin:0 auto 14px; border-radius:50%; background:#169b9b; color:#fff; font-size:1.6rem; font-weight:900; }
.registration-success-content h3 { margin:0 0 8px; font-size:1rem; }
.registration-success-content > p { color:var(--muted-text, #8d97a5); line-height:1.6; }
.registration-success-id { display:flex; flex-direction:column; gap:4px; margin:14px 0; padding:12px; border-radius:12px; background:rgba(127,127,127,.06); }
.registration-success-id span { font-size:.68rem; color:var(--muted-text, #8d97a5); }
.registration-success-id strong { font-size:.9rem; }
.registration-payment-review { display:grid; grid-template-columns:1.5fr 1fr 1fr; gap:10px; margin:12px 0; }
.registration-payment-review > div { display:flex; flex-direction:column; gap:3px; padding:12px; border-radius:12px; background:rgba(127,127,127,.05); }
.registration-payment-review span { font-size:.65rem; color:var(--muted-text, #8d97a5); text-transform:uppercase; }
.registration-payment-review strong { font-size:.84rem; }
.registration-payment-review small { color:var(--muted-text, #8d97a5); }
.registration-file-actions { display:flex; gap:8px; flex-wrap:wrap; margin-bottom:12px; }
.registration-file-actions button { border:1px solid rgba(22,155,155,.25); background:rgba(22,155,155,.07); color:#169b9b; border-radius:10px; padding:8px 11px; font-size:.72rem; font-weight:800; cursor:pointer; }
.registration-file-preview { margin:10px 0 14px; padding:10px; border-radius:14px; background:#0e1724; text-align:center; }
.registration-file-preview img, .registration-file-preview iframe { width:100%; max-height:360px; object-fit:contain; border:0; border-radius:10px; background:#fff; }
.registration-file-preview button { margin-top:8px; border:0; border-radius:9px; padding:7px 12px; cursor:pointer; }
@media (max-width: 680px) {
  .registration-order-summary { grid-template-columns:1fr; }
  .registration-bank-list { grid-template-columns:1fr; }
  .registration-payment-review { grid-template-columns:1fr; }
  .registration-stepper { padding-left:18px; padding-right:18px; }
}


