/* V30 — CEO Finance & Product Monitoring */
.ceo-finance-monitoring { margin:20px 0; }
.ceo-finance-summary { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:12px; margin-bottom:14px; }
.ceo-finance-summary > article { padding:16px; border-radius:16px; border:1px solid rgba(127,127,127,.14); background:rgba(127,127,127,.035); display:flex; flex-direction:column; gap:5px; }
.ceo-finance-summary span { font-size:.66rem; color:var(--muted-text,#8d97a5); text-transform:uppercase; letter-spacing:.05em; }
.ceo-finance-summary strong { font-size:1.18rem; }
.ceo-finance-summary small { color:var(--muted-text,#8d97a5); font-size:.7rem; }

.ceo-monitor-panel { padding:17px; border:1px solid rgba(127,127,127,.14); border-radius:17px; background:rgba(127,127,127,.03); margin-bottom:14px; }
.ceo-monitor-panel > header { display:flex; align-items:flex-end; justify-content:space-between; gap:12px; margin-bottom:13px; }
.ceo-monitor-panel > header h3 { margin:4px 0 0; font-size:1rem; }
.ceo-monitor-panel > header > small { color:var(--muted-text,#8d97a5); }

.ceo-tuition-trend { display:grid; grid-template-columns:repeat(6,minmax(0,1fr)); gap:9px; }
.ceo-tuition-month { padding:11px; border-radius:12px; background:rgba(127,127,127,.045); }
.ceo-tuition-month-head, .ceo-tuition-meta { display:flex; justify-content:space-between; gap:6px; align-items:center; }
.ceo-tuition-month-head strong { font-size:.75rem; }
.ceo-tuition-month-head span { font-size:.7rem; font-weight:800; color:#169b9b; }
.ceo-tuition-progress { height:7px; border-radius:999px; background:rgba(127,127,127,.12); overflow:hidden; margin:9px 0; }
.ceo-tuition-progress i { display:block; height:100%; border-radius:999px; background:#169b9b; }
.ceo-tuition-meta span { color:var(--muted-text,#8d97a5); font-size:.62rem; }
.ceo-tuition-meta strong { font-size:.68rem; }

.ceo-product-grid { display:grid; grid-template-columns:1fr 1fr; gap:14px; }
.ceo-product-grid .ceo-monitor-panel { margin-bottom:0; min-width:0; }
.ceo-product-list { display:flex; flex-direction:column; max-height:360px; overflow:auto; padding-right:4px; }
.ceo-product-list > div { display:grid; grid-template-columns:1fr auto; gap:10px; align-items:center; padding:10px 0; border-top:1px solid rgba(127,127,127,.1); }
.ceo-product-list > div:first-child { border-top:0; }
.ceo-product-list > div > div:first-child { display:flex; flex-direction:column; gap:2px; min-width:0; }
.ceo-product-list strong { font-size:.78rem; overflow-wrap:anywhere; }
.ceo-product-list span { color:var(--muted-text,#8d97a5); font-size:.66rem; }
.ceo-product-status { display:flex; flex-direction:column; align-items:flex-end; gap:3px; text-align:right; }
.ceo-product-status b { max-width:145px; font-size:.66rem; color:#169b9b; }
.ceo-product-status small { color:var(--muted-text,#8d97a5); font-size:.64rem; }
.ceo-monitor-empty { margin:0; color:var(--muted-text,#8d97a5); font-size:.76rem; }

@media (max-width:900px) {
  .ceo-finance-summary { grid-template-columns:1fr 1fr; }
  .ceo-tuition-trend { grid-template-columns:repeat(3,1fr); }
}
@media (max-width:680px) {
  .ceo-finance-summary, .ceo-product-grid { grid-template-columns:1fr; }
  .ceo-tuition-trend { grid-template-columns:1fr 1fr; }
}

/* V31 — force icon-only light/dark controls */
.icon-only-theme-switch button {
  font-size: 0 !important;
}
.icon-only-theme-switch button svg {
  width: 18px;
  height: 18px;
  display: block;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.9;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.icon-only-theme-switch button svg circle {
  fill: none;
}

/* V32 — Login theme buttons are hard-wired SVG icons only */
.login-top-controls .login-theme-icons {
  position: static !important;
  min-height: 42px !important;
  margin: 0 !important;
  padding: 4px !important;
  display: flex !important;
  align-items: center !important;
  gap: 2px !important;
  border: 1px solid var(--ui-line) !important;
  border-radius: 14px !important;
  background: color-mix(in srgb, var(--ui-surface) 92%, transparent) !important;
  box-shadow: var(--ui-shadow-soft) !important;
  backdrop-filter: blur(18px) !important;
  -webkit-backdrop-filter: blur(18px) !important;
}
.login-top-controls .login-theme-icons button {
  width: 40px !important;
  min-width: 40px !important;
  height: 32px !important;
  min-height: 32px !important;
  padding: 0 !important;
  display: grid !important;
  place-items: center !important;
  border: 0 !important;
  border-radius: 10px !important;
  color: var(--ui-muted) !important;
  background: transparent !important;
  font-size: 0 !important;
  line-height: 0 !important;
}
.login-top-controls .login-theme-icons button.active {
  color: #05202a !important;
  background: var(--ui-accent) !important;
}
.login-top-controls .login-theme-icons svg {
  display: block !important;
  width: 18px !important;
  height: 18px !important;
  fill: none !important;
  stroke: currentColor !important;
  stroke-width: 1.9 !important;
  stroke-linecap: round !important;
  stroke-linejoin: round !important;
}


/* V34 — Registration: Data → Program/Jadwal → Pembayaran */
.registration-stepper-three > span { min-width:0; white-space:nowrap; }
.registration-data-summary { margin-bottom:18px; }
.registration-stepper-three { overflow-x:auto; scrollbar-width:none; }
.registration-stepper-three::-webkit-scrollbar { display:none; }
@media (max-width:680px) {
