}

/* V44 — light mode readability / contrast guardrails */
html[data-theme='light'] {
  --v44-text:#102337;
  --v44-muted:#52697d;
  --v44-line:#b9cfdb;
  --v44-surface:#ffffff;
  --v44-soft:#f5f9fc;
  --v44-error-text:#8f1d2c;
  --v44-error-bg:#fff0f2;
  --v44-error-line:#d96a78;
}

html[data-theme='light'] .student-access-modal,
html[data-theme='light'] .registration-checkout-section,
html[data-theme='light'] .registration-order-summary,
html[data-theme='light'] .registration-account-note,
html[data-theme='light'] .registration-checkout-note,
