/* V60 — Report radar chart */
.report-skill-chart-card {
  overflow:hidden;
}
.academic-radar {
  position:relative;
  width:min(100%,420px);
  aspect-ratio:1/1;
  margin:12px auto 0;
}
.academic-radar svg {
  display:block;
  width:72%;
  height:72%;
  margin:14% auto;
  overflow:visible;
}
.academic-radar-grid {
  fill:none;
  stroke:#c9d6e0;
  stroke-width:1;
}
.academic-radar-axis {
  stroke:#d6e0e8;
  stroke-width:1;
}
.academic-radar-value {
  fill:rgba(38,122,240,.14);
  stroke:#267af0;
  stroke-width:3;
}
.academic-radar-dot {
  fill:#267af0;
}
.academic-radar-label {
  position:absolute;
  display:flex;
  flex-direction:column;
  align-items:center;
  max-width:34%;
  color:#758596;
  font-size:.62rem;
  line-height:1.2;
  text-align:center;
}
.academic-radar-label strong {
  margin-top:2px;
  color:#172235;
  font-size:.74rem;
}
.academic-radar-label.top { top:0; left:33%; }
.academic-radar-label.right { right:0; top:43%; align-items:flex-start; text-align:left; }
.academic-radar-label.bottom { bottom:0; left:33%; }
.academic-radar-label.left { left:0; top:43%; align-items:flex-end; text-align:right; }
html[data-theme='dark'] .academic-radar-grid,
html[data-theme='dark'] .academic-radar-axis { stroke:#334554; }
html[data-theme='dark'] .academic-radar-value { fill:rgba(37,197,212,.12); stroke:#25c5d4; }
html[data-theme='dark'] .academic-radar-dot { fill:#25c5d4; }
html[data-theme='dark'] .academic-radar-label { color:#8fa1af; }
